34	#define ASCEND_SHARED_MEM_SIZE 196352
35	#define ASCEND_SHARED_DYN_MEM_SIZE 524032
36	#define ASCEND_WMMA_MATRIX_A_MEM_SIZE 65536
37	#define ASCEND_WMMA_MATRIX_B_MEM_SIZE 65536
