51	static size_t AlignUp(size_t value, size_t alignment) {
52	  return ((value + alignment - 1) / alignment) * alignment;
53	}
54	
55	class AscendMemoryPlanning : public arith::IRMutatorWithAnalyzer {
56	public:
57	  static PrimFunc Substitute(PrimFunc f, PassContext ctx) {
58	    bool auto_ascend_memory_planning =
59	        ctx->GetConfig<Bool>(kAscendMemoryPlanning, Bool(false)).value();
60	
61	    PrimFuncNode *fptr = f.CopyOnWrite();
62	    auto fn_attr = fptr->attrs.CopyOnWrite();
63	
64	    Map<Var, PrimExpr> external_address_map;
65	    if (fn_attr->dict.count("address_map")) {
66	      external_address_map =
67	          fn_attr->dict.at("address_map").as<Map<Var, PrimExpr>>().value();
68	    }
69	
70	    Map<Var, Array<PrimExpr>> external_shape_map;
71	    if (fn_attr->dict.count(kLogicBufferShapes)) {
72	      external_shape_map = fn_attr->dict.at(kLogicBufferShapes)
73	                               .as<Map<Var, Array<PrimExpr>>>()
74	                               .value();
75	    } else if (fn_attr->dict.count("buffer_shapess")) {
76	      external_shape_map = fn_attr->dict.at("buffer_shapess")
77	                               .as<Map<Var, Array<PrimExpr>>>()
78	                               .value();
79	    }
80	
81	    AscendMemoryPlanner planner(f, external_address_map, external_shape_map,
82	                                auto_ascend_memory_planning);
83	    auto address_map = planner.GetAddressMap();
84	    auto buffer_sizes = planner.GetBufferSizes();
85	
86	    Map<Var, PrimExpr> address_map_attr;
87	    for (const auto &kv : address_map) {
88	      Var buffer_var = GetRef<Var>(kv.first);
89	      address_map_attr.Set(buffer_var, Integer(kv.second));
90	    }
91	    fn_attr->dict.Set("address_map", address_map_attr);
92	
93	    Map<Var, PrimExpr> size_map_attr;
94	    for (const auto &kv : buffer_sizes) {
95	      Var buffer_var = GetRef<Var>(kv.first);
96	      size_map_attr.Set(buffer_var, Integer(static_cast<int64_t>(kv.second)));
97	    }
98	    fn_attr->dict.Set("size_map", size_map_attr);
99	    return f;
100	  }
101	
102	private:
103	  class AscendMemoryPlanner : public StmtExprVisitor {
104	  public:
105	    explicit AscendMemoryPlanner(const PrimFunc &func,
106	                                 Map<Var, PrimExpr> external_address_map,
107	                                 Map<Var, Array<PrimExpr>> external_shape_map,
108	                                 bool auto_plan = false) {
109	      memory_auto_plan = auto_plan;
110	      // Preserve layouts needed by CalculateBufferSize.
111	      // PTO 4D shapes are [physical_M, physical_N, valid_M, valid_N].
112	      external_shape_map_ = external_shape_map;
113	      memory_limits_ = {{"shared.l1", ASCEND_SHARED_DYN_MEM_SIZE},
114	                        {"wmma.matrix_a", ASCEND_WMMA_MATRIX_A_MEM_SIZE},
115	                        {"wmma.matrix_b", ASCEND_WMMA_MATRIX_B_MEM_SIZE},
116	                        {"wmma.accumulator", ASCEND_WMMA_ACCUMULATOR_MEM_SIZE},
117	                        {"shared.ub", ASCEND_SHARED_MEM_SIZE}};
118	
119	      SetPreAllocBuffer(external_address_map);
120	      SetTmpBuffers(external_shape_map);
121	
122	      operator()(func->body);
123	      PlanMemory();
124	    }
125	
126	    const std::unordered_map<const VarNode *, int64_t> &GetAddressMap() const {
127	      return address_map_;
128	    }
129	
130	    const std::unordered_map<const VarNode *, size_t> &GetBufferSizes() const {
131	      return buffer_sizes_;
132	    }
133	
134	  private:
135	    struct StorageEntry {
136	      uint64_t const_nbits{0};
137	      std::vector<std::vector<const VarNode *>> allocs;
138	    };
139	
140	    struct StmtEntry {
141	      const Object *stmt{};
142	      int64_t scope_pair_offset{0};
143	      std::vector<const VarNode *> touched;
144	    };
145	
146	    struct EventEntry {
147	      std::vector<const VarNode *> gen;
148	      std::vector<const VarNode *> kill;
149	    };
150	
151	    struct AllocEntry {
152	      size_t level{0};
153	      const AllocateNode *alloc{nullptr};
154	    };
155	
156	    struct StmtAttr {
157	      size_t level{0};
158	    };
159	
160	    // Track a buffer touch for NPU shared memory.
161	    void TrackBufferTouch(const VarNode *buf) {
162	      auto it = alloc_info_.find(buf);
163	      if (it != alloc_info_.end() && it->second.alloc) {
164	        if (IsNPUSharedMemory(GetRef<Var>(buf))) {
165	          scope_.back().touched.push_back(buf);
166	
167	          if (first_use_.count(buf) == 0) {
168	            first_use_[buf] = linear_seq_.size();
169	            DLOG(DEBUG) << "First use of buffer " << buf->name_hint
170	                        << " at statement index " << linear_seq_.size();
171	          }
172	        }
173	      }
174	    }
175	
176	    void VisitStmt_(const AllocateNode *op) final {
177	      size_t level = scope_.size();
178	      const VarNode *buf = op->buffer_var.get();
179	
180	      alloc_info_[buf].alloc = op;
181	      alloc_info_[buf].level = level;
182	
183	      if (IsNPUSharedMemory(op->buffer_var)) {
184	        ICHECK(buffer_names_.find(buf->name_hint) == buffer_names_.end())
185	            << "Duplicate buffer name found: " << buf->name_hint
186	            << ". Please ensure all buffers have unique names.";
187	        buffer_names_.insert(buf->name_hint);
188	
189	        std::string scope = GetPtrStorageScope(op->buffer_var);
190	        if (memory_limits_.count(scope)) {
191	          buffer_scopes_[buf] = scope;
192	          origin_buffer.push_back(buf);
193	          buffer_sizes_[buf] = CalculateBufferSize(op);
194	
195	          DLOG(DEBUG) << "Found NPU memory allocation: "
196	                      << op->buffer_var->name_hint << " scope=" << scope
197	                      << " size=" << buffer_sizes_[buf] << " bytes";
198	        }
199	      }
200	
201	      StmtExprVisitor::VisitStmt_(op);
202	    }
203	
204	    void VisitStmt_(const BufferStoreNode *op) final {
205	      scope_.push_back(StmtEntry());
206	      StmtExprVisitor::VisitStmt_(op);
207	
208	      TrackBufferTouch(op->buffer->data.get());
209	
210	      StmtEntry e = scope_.back();
211	      scope_.pop_back();
212	      if (!e.touched.empty()) {
213	        e.stmt = op;
214	        UpdateStmtAttr(op, scope_level_);
215	        linear_seq_.push_back(e);
216	      }
217	    }
218	
219	    void VisitStmt_(const EvaluateNode *op) final {
220	      scope_.push_back(StmtEntry());
221	      StmtExprVisitor::VisitStmt_(op);
222	
223	      StmtEntry e = scope_.back();
224	      scope_.pop_back();
225	      if (!e.touched.empty()) {
226	        e.stmt = op;
227	        UpdateStmtAttr(op, scope_level_);
228	        linear_seq_.push_back(e);
229	      }
230	    }
231	
232	    void VisitExpr_(const BufferLoadNode *op) final {
233	      StmtExprVisitor::VisitExpr_(op);
234	      TrackBufferTouch(op->buffer->data.get());
235	    }
236	
237	    void VisitExpr_(const VarNode *buf) final { TrackBufferTouch(buf); }
238	
239	    void VisitExpr_(const CallNode *op) final {
240	      if (op->op.same_as(builtin::tvm_access_ptr())) {
241	        Var buffer = Downcast<Var>(op->args[1]);
242	        if (IsNPUSharedMemory(buffer)) {
243	          TrackBufferTouch(buffer.get());
244	        }
245	      }
246	      StmtExprVisitor::VisitExpr_(op);
247	    }
248	
249	    // Cal Scope level and save linear stmt event
250	    template <typename T> void VisitNewScope(const T *op) {
251	      scope_.push_back(StmtEntry());
252	      StmtEntry e;
253	      e.stmt = op;
254	      UpdateStmtAttr(op, scope_level_);
255	      int64_t begin_index = static_cast<int64_t>(linear_seq_.size());
256	
257	      linear_seq_.push_back(e);
258	      StmtExprVisitor::VisitStmt_(op);
259	
260	      e.touched = std::move(scope_.back().touched);
261	      scope_.pop_back();
262	      int64_t end_index = static_cast<int64_t>(linear_seq_.size());
263	
264	      e.scope_pair_offset = begin_index - end_index;
265	      linear_seq_.push_back(e);
266	      linear_seq_[begin_index].scope_pair_offset = end_index - begin_index;
267	    }
268	
269	    void VisitStmt_(const AttrStmtNode *op) final { VisitNewScope(op); }
270	    void VisitStmt_(const IfThenElseNode *op) final { VisitNewScope(op); }
271	    void VisitStmt_(const ForNode *op) final {
272	      scope_level_++;
273	      VisitNewScope(op);
274	      scope_level_--;
275	    }
276	    void VisitStmt_(const WhileNode *op) final { VisitNewScope(op); }
277	    void VisitStmt_(const AssertStmtNode *op) final { VisitNewScope(op); }
278	    void VisitStmt_(const LetStmtNode *op) final { VisitNewScope(op); }
