280	    void SetPreAllocBuffer(Map<Var, PrimExpr> external_address_map) {
281	      for (const auto &kv : external_address_map) {
282	        const VarNode *buf = kv.first.get();
283	        int64_t addr_offset = kv.second.as<IntImmNode>()->value;
284	        if (pre_alloc_buffer_.count(buf->name_hint)) {
285	          LOG(FATAL) << "Buffer " << buf->name_hint
286	                     << " already been allocated.";
287	        }
288	        pre_alloc_buffer_[buf->name_hint] = addr_offset;
289	      }
290	    }
291	
292	    void SetTmpBuffers(Map<Var, Array<PrimExpr>> external_shape_map) {
293	      for (auto &kv : external_shape_map) {
294	        const VarNode *buf = kv.first.get();
295	        std::string scope = GetPtrStorageScope(kv.first);
296	        if (!pre_alloc_buffer_.count(buf->name_hint) && scope == "shared.ub") {
297	          tmp_buffers.push_back(buf);
298	        }
299	      }
300	    }
301	
302	    void PlanMemory() {
303	      LivenessAnalysis();
304	      CollectLoopInfo();
305	
306	      std::unordered_map<std::string, std::vector<const VarNode *>>
307	          scope_groups;
308	      for (const auto &kv : buffer_scopes_) {
309	        scope_groups[kv.second].push_back(kv.first);
310	      }
311	
312	      DLOG(DEBUG) << "Memory planning by scope groups:";
313	      for (const auto &kv : scope_groups) {
314	        DLOG(DEBUG) << "  Scope " << kv.first << ": " << kv.second.size()
315	                    << " buffers";
316	      }
317	
318	      for (const auto &scope_kv : scope_groups) {
319	        if (memory_auto_plan)
320	          PlanMemoryForScope(scope_kv.first, scope_kv.second);
321	        else
322	          PlanMemoryForScopeLinear(scope_kv.first, scope_kv.second);
323	      }
324	    }
325	
326	    void LivenessAnalysis() {
327	      std::unordered_set<const VarNode *> touched;
328	      for (size_t i = linear_seq_.size(); i != 0; --i) {
329	        const StmtEntry &s = linear_seq_[i - 1];
330	        for (const VarNode *buffer : s.touched) {
331	          if (!touched.count(buffer)) {
332	            touched.insert(buffer);
333	            event_map_[s.stmt].kill.push_back(buffer);
334	          }
335	        }
336	      }
337	
338	      for (size_t i = 0; i < linear_seq_.size(); ++i) {
339	        const StmtEntry &s = linear_seq_[i];
340	        for (const VarNode *buffer : s.touched) {
341	          if (first_use_.count(buffer) && first_use_[buffer] == i) {
342	            event_map_[s.stmt].gen.push_back(buffer);
343	          }
344	        }
345	      }
346	
347	      ReorderKillPoints();
348	
349	      DLOG(DEBUG) << "Liveness Analysis Results:";
350	      for (const auto &event_pair : event_map_) {
351	        const EventEntry &entry = event_pair.second;
352	        if (entry.gen.empty() && entry.kill.empty())
353	          continue;
354	
355	        std::stringstream gen_ss, kill_ss;
356	        for (const VarNode *var : entry.gen)
357	          gen_ss << var->name_hint << " ";
358	        for (const VarNode *var : entry.kill)
359	          kill_ss << var->name_hint << " ";
360	
361	        DLOG(DEBUG) << "  Statement: " << event_pair.first->GetTypeKey();
362	        if (!entry.gen.empty())
363	          DLOG(DEBUG) << "    GEN: " << gen_ss.str();
364	        if (!entry.kill.empty())
365	          DLOG(DEBUG) << "    KILL: " << kill_ss.str();
366	      }
367	    }
368	
369	    void ReorderKillPoints() {
370	      std::vector<StmtEntry> gen_kill_seq;
371	      for (const auto &stmt_entry : linear_seq_) {
372	        if (!event_map_[stmt_entry.stmt].gen.empty() ||
373	            !event_map_[stmt_entry.stmt].kill.empty()) {
374	          gen_kill_seq.push_back(stmt_entry);
375	        }
376	      }
377	
378	      for (auto &event_pair : event_map_) {
379	        const Object *stmt = event_pair.first;
380	        EventEntry &event = event_pair.second;
381	
382	        if (event.kill.empty())
383	          continue;
384	
385	        ICHECK(stmt_attrs_.count(stmt));
386	        int kill_level = stmt_attrs_.at(stmt).level;
387	
388	        std::unordered_set<const VarNode *> visited_buffers;
389	
390	        for (auto it = event.kill.begin(); it != event.kill.end();) {
391	          const VarNode *buffer = *it;
392	          bool found_gen = false;
393	          int gen_level = 0;
394	
395	          for (const auto &gen_pair : event_map_) {
396	            const auto &gen_event = gen_pair.second;
397	            if (std::find(gen_event.gen.begin(), gen_event.gen.end(), buffer) !=
398	                gen_event.gen.end()) {
399	              found_gen = true;
400	              gen_level = stmt_attrs_.at(gen_pair.first).level;
401	              break;
402	            }
403	          }
404	
405	          if (found_gen && kill_level > gen_level) {
406	            if (visited_buffers.count(buffer)) {
407	              ++it;
408	              continue;
409	            }
410	
411	            it = event.kill.erase(it);
412	
413	            const Object *last_stmt_at_level = nullptr;
414	            auto stmt_it = gen_kill_seq.begin();
415	            for (; stmt_it != gen_kill_seq.end(); ++stmt_it) {
416	              if (stmt_it->stmt == stmt) {
417	                break;
418	              }
419	            }
420	
421	            for (; stmt_it != gen_kill_seq.end(); ++stmt_it) {
422	              auto next_it = stmt_it + 1;
423	              if (next_it == gen_kill_seq.end() ||
424	                  stmt_attrs_.at(next_it->stmt).level == gen_level - 1) {
425	                last_stmt_at_level = stmt_it->stmt;
426	                break;
427	              }
428	            }
429	
430	            if (last_stmt_at_level) {
431	              event_map_[last_stmt_at_level].kill.push_back(buffer);
432	              visited_buffers.insert(buffer);
433	            }
434	          } else {
435	            ++it;
436	          }
437	        }
438	      }
439	    }
440	
441	    int64_t FindEventIndex(const VarNode *buffer, bool use_gen) {
442	      for (const auto &event_pair : event_map_) {
443	        const EventEntry &event = event_pair.second;
444	        const auto &vec = use_gen ? event.gen : event.kill;
445	        auto it = std::find(vec.begin(), vec.end(), buffer);
446	        if (it != vec.end()) {
447	          for (size_t i = 0; i < linear_seq_.size(); ++i) {
448	            if (linear_seq_[i].stmt == event_pair.first) {
449	              return static_cast<int64_t>(i);
450	            }
451	          }
452	          break;
453	        }
454	      }
455	      return -1;
456	    }
457	
458	    /*!
459	     * \brief Collect loop intervals and buffer touch indices for
460	     *        loop-aware liveness extension.
461	     *
462	     * After LivenessAnalysis, the KILL point of a buffer is set to its
463	     * last touch in the linearized IR.  However, when a buffer is
464	     * defined *before* a loop and touched *inside* the loop body, it
465	     * is actually live across every iteration — its real KILL should
466	     * be the loop's end, not the textual last touch inside the body.
467	     *
468	     * This method pre-computes:
469	     *   1. loop_intervals_  — [begin, end] index pairs for every
470	     *      ForNode / WhileNode in linear_seq_.
471	     *   2. buffer_touch_indices_ — for every buffer, a sorted set of
472	     *      all linear_seq_ indices where it is touched.
473	     */
474	    void CollectLoopInfo() {
475	      for (size_t i = 0; i < linear_seq_.size(); ++i) {
476	        const StmtEntry &s = linear_seq_[i];
477	        if (s.scope_pair_offset > 0 && s.stmt &&
478	            (s.stmt->IsInstance<ForNode>() ||
479	             s.stmt->IsInstance<WhileNode>())) {
480	          int64_t begin = static_cast<int64_t>(i);
481	          int64_t end = begin + s.scope_pair_offset;
482	          loop_intervals_.push_back({begin, end});
483	        }
484	      }
485	
486	      for (size_t i = 0; i < linear_seq_.size(); ++i) {
487	        for (const VarNode *buf : linear_seq_[i].touched) {
488	          buffer_touch_indices_[buf].insert(static_cast<int64_t>(i));
489	        }
490	      }
491	    }
492	
493	    /*!
494	     * \brief Extend a buffer's KILL index to cover loops in which it
495	     *        is live across iterations.
496	     *
497	     * The linearized IR represents a loop body as a single pass, so the
498	     * liveness analysis computes a buffer's KILL as the last touch
499	     * *within one iteration*.  However, when a buffer is defined
500	     * *before* a loop and touched *inside* the loop body, it is
501	     * actually live across every iteration — its real KILL should be
502	     * the loop's end, not the textual last touch inside the body.
503	     *
504	     * This handles the case where a buffer (e.g. index_ub) is
505	     * initialized once before a segment loop and read in every
506	     * iteration.  Without this extension, the planner may reuse the
507	     * buffer's memory for another buffer (e.g. merged_ub) that is
508	     * written inside the same loop, causing silent data corruption.
509	     *
510	     * For each loop [loop_begin, loop_end] where:
511	     *   - GEN < loop_begin  (buffer defined before the loop)
512	     *   - loop_begin <= KILL < loop_end  (buffer's last touch is inside)
513	     * the KILL is extended to loop_end.  This applies to all enclosing
514	     * loops, so we take the maximum loop_end.
515	     */
516	    int64_t ExtendKillIndex(const VarNode *buffer, int64_t gen_idx,
517	                            int64_t kill_idx) {
518	      if (kill_idx < 0) {
519	        return kill_idx;
520	      }
521	      auto it = buffer_touch_indices_.find(buffer);
522	      if (it == buffer_touch_indices_.end()) {
523	        return kill_idx;
524	      }
525	      const std::set<int64_t> &touches = it->second;
526	
527	      int64_t extended = kill_idx;
528	      for (const auto &loop : loop_intervals_) {
529	        int64_t loop_begin = loop.first;
530	        int64_t loop_end = loop.second;
531	
532	        if (gen_idx < loop_begin && kill_idx >= loop_begin &&
533	            kill_idx < loop_end) {
534	          auto touch_it = touches.upper_bound(loop_begin);
535	          if (touch_it != touches.end() && *touch_it < loop_end) {
536	            extended = std::max(extended, loop_end);
537	          }
538	        }
539	      }
540	      return extended;
541	    }
542	
543	    void PlanMemoryForScope(const std::string &scope,
544	                            const std::vector<const VarNode *> &buffers) {
545	      DLOG(DEBUG) << "Planning memory for scope: " << scope;
546	
547	      std::vector<LiveInterval> intervals;
548	      std::unordered_map<const VarNode *, int64_t> pre_alloc_scope_buffer;
549	      for (const VarNode *buffer : buffers) {
550	        if (pre_alloc_buffer_.count(buffer->name_hint) > 0) {
551	          pre_alloc_scope_buffer[buffer] = pre_alloc_buffer_[buffer->name_hint];
552	        };
553	
554	        int64_t start = FindEventIndex(buffer, true);
555	        int64_t end = FindEventIndex(buffer, false);
556	
557	        if (start != -1 && end != -1) {
558	          end = ExtendKillIndex(buffer, start, end);
559	          intervals.emplace_back(buffer, start, end, buffer_sizes_[buffer]);
560	          DLOG(DEBUG) << "Buffer " << buffer->name_hint << ": [" << start
561	                      << ", " << end << "], size=" << buffer_sizes_[buffer];
562	        }
563	      }
564	
565	      std::sort(intervals.begin(), intervals.end(),
566	                [](const LiveInterval &a, const LiveInterval &b) {
567	                  return a.start < b.start;
568	                });
569	
570	      LinearScanAllocator allocator(memory_limits_[scope],
571	                                    pre_alloc_scope_buffer);
572	      auto allocations = allocator.allocate(intervals);
573	
574	      for (const auto &alloc : allocations) {
575	        address_map_[alloc.buffer] = alloc.offset;
576	        DLOG(DEBUG) << "Allocated buffer " << alloc.buffer->name_hint
577	                    << " at offset " << alloc.offset << " (size=" << alloc.size
578	                    << ")";
579	      }
580	
581	      size_t total_used = 0;
582	      for (const auto &alloc : allocations) {
583	        total_used = std::max(total_used, alloc.offset + alloc.size);
584	      }
585	
586	      DLOG(DEBUG) << "Scope " << scope << " memory usage: " << total_used << "/"
587	                  << memory_limits_[scope] << " bytes ("
588	                  << (total_used * 100.0 / memory_limits_[scope]) << "%)";
589	      if (total_used > memory_limits_[scope]) {
590	        DLOG(WARNING) << "Memory limit exceeded for scope " << scope << ": "
591	                      << total_used << " > " << memory_limits_[scope];
592	      }
593	    }
594	
595	    void PlanMemoryForScopeLinear(const std::string &scope,
596	                                  const std::vector<const VarNode *> &buffers) {
597	      bool check_overflow = false; // reserve memory overflow check
598	      int64_t current_offset = 0;
599	      int64_t max_offset = 0;
600	
601	      // Allocate origin buffer first, then tmp buffer in shared memory
602	      auto alloc_buffer = [&](const VarNode *buffer, int64_t &offset,
603	                              const std::string &err_prefix) -> bool {
604	        int64_t buf_size = buffer_sizes_[buffer];
605	        if (offset + buf_size > memory_limits_[scope] && check_overflow) {
606	          LOG(FATAL) << err_prefix << " Out of memory in scope: " << scope
607	                     << "\nBuffer: " << buffer->name_hint
608	                     << "\nRequired size: " << buf_size
609	                     << "\nCurrent offset: " << offset
610	                     << "\nMemory limit: " << memory_limits_[scope];
611	          return false;
612	        }
613	        address_map_[buffer] = offset;
614	        offset = static_cast<int64_t>(AlignUp(offset + buf_size, 32));
615	        return true;
616	      };
617	
618	      for (const VarNode *buffer : origin_buffer) {
619	        if (std::find(buffers.begin(), buffers.end(), buffer) ==
620	            buffers.end()) {
621	          continue;
622	        }
623	        if (pre_alloc_buffer_.count(buffer->name_hint)) {
624	          address_map_[buffer] = pre_alloc_buffer_[buffer->name_hint];
625	          max_offset = std::max(
626	              max_offset,
627	              static_cast<int64_t>(pre_alloc_buffer_[buffer->name_hint] +
628	                                   buffer_sizes_[buffer]));
629	        } else if (scope != "shared.ub") {
630	          alloc_buffer(buffer, current_offset,
631	                       "Linear memory allocation failed!");
632	          max_offset = std::max(max_offset, current_offset);
633	        }
634	      }
635	      // Allocate tmp buffer/default buffer after origin buffer to avoid
636	      // fragmention in shared memory
637	      if (scope == "shared.ub") {
638	        for (const VarNode *buffer : origin_buffer) {
639	          if (std::find(tmp_buffers.begin(), tmp_buffers.end(), buffer) !=
640	                  tmp_buffers.end() &&
641	              !address_map_.count(buffer)) {
642	            alloc_buffer(buffer, max_offset,
643	                         "Linear tmp memory allocation failed!");
644	          }
645	        }
646	      }
647	    }
648	
649	    struct LiveInterval {
650	      const VarNode *buffer;
651	      int64_t start;
652	      int64_t end;
653	      size_t size;
654	
655	      LiveInterval(const VarNode *buf, int64_t s, int64_t e, size_t sz)
656	          : buffer(buf), start(s), end(e), size(sz) {}
657	    };
658	
659	    struct Allocation {
660	      const VarNode *buffer;
661	      size_t offset;
662	      size_t size;
663	      bool is_reused;
664	    };
665	
666	    class LinearScanAllocator {
667	    public:
668	      LinearScanAllocator(
669	          size_t memory_limit,
670	          const std::unordered_map<const VarNode *, int64_t> &pre_alloc_buffer)
671	          : memory_limit_(memory_limit), next_new_offset_(0),
672	            pre_alloc_buffer_(pre_alloc_buffer) {}
673	
674	      std::vector<Allocation> allocate(std::vector<LiveInterval> &intervals) {
675	        std::vector<Allocation> allocations;
676	
677	        for (auto &interval : intervals)
678	          buffer_map_[interval.buffer] = &interval;
679	
680	        std::sort(intervals.begin(), intervals.end(),
681	                  [](const LiveInterval &a, const LiveInterval &b) {
682	                    return a.start < b.start;
683	                  });
684	
685	        auto end_time_compare = [](const LiveInterval &a,
686	                                   const LiveInterval &b) {
687	          return a.end > b.end;
688	        };
689	        std::priority_queue<LiveInterval, std::vector<LiveInterval>,
690	                            decltype(end_time_compare)>
691	            active_queue(end_time_compare);
692	
693	        std::vector<Allocation> active_allocations;
694	        std::vector<std::pair<size_t, size_t>> free_blocks;
695	
696	        for (auto &interval : intervals) {
697	          DLOG(DEBUG) << "Processing: " << interval.buffer->name_hint << " ["
698	                      << interval.start << ", " << interval.end
699	                      << "] size=" << interval.size;
700	
701	          while (!active_queue.empty() &&
702	                 active_queue.top().end <
703	                     interval.start) { // Free unactivate buffer
704	            const auto &expired = active_queue.top();
705	
706	            auto it = std::find_if(active_allocations.begin(),
707	                                   active_allocations.end(),
708	                                   [&](const Allocation &alloc) {
709	                                     return alloc.buffer == expired.buffer;
710	                                   });
711	            if (it != active_allocations.end()) {
712	              free_blocks.emplace_back(it->offset, it->size);
713	              active_allocations.erase(it);
714	
715	              DLOG(DEBUG) << "  Released for reuse: "
716	                          << expired.buffer->name_hint << " at offset "
717	                          << it->offset;
718	            }
719	
720	            active_queue.pop();
721	          }
722	
723	          mergeFreeBlocks(free_blocks);
724	
725	          size_t allocated_offset;
726	          bool is_reused = false;
727	
728	          auto pre_it = pre_alloc_buffer_.find(interval.buffer);
729	          if (pre_it != pre_alloc_buffer_.end()) { // Pre alloc
730	            allocated_offset = AlignUp(static_cast<size_t>(pre_it->second), 32);
731	            size_t allocated_end = allocated_offset + interval.size;
732	
733	            for (const auto &active : active_allocations) {
734	              if (allocated_offset < active.offset + active.size &&
735	                  active.offset < allocated_offset + interval.size) {
736	                LOG(FATAL) << "Memory allocation failed for: "
737	                           << pre_it->first->name_hint
738	                           << " memory allocate conflict with: "
739	                           << interval.buffer->name_hint << " at "
740	                           << allocated_offset;
741	                continue;
742	              }
743	            }
744	
745	            if (allocated_offset > next_new_offset_) {
746	              free_blocks.emplace_back(next_new_offset_,
747	                                       allocated_offset - next_new_offset_);
748	            }
749	
750	            if (allocated_end > next_new_offset_) {
751	              next_new_offset_ = allocated_end;
752	            }
753	
754	          } else { // Normal Alloc
755	            size_t new_memory_offset = AlignUp(next_new_offset_, 32);
756	            if (new_memory_offset + interval.size <= memory_limit_ &&
757	                !CheckConflict(new_memory_offset, interval)) {
758	              allocated_offset = new_memory_offset;
759	              next_new_offset_ = new_memory_offset + interval.size;
760	            } else {
761	              allocated_offset = findReusableBlock(interval, free_blocks);
762	              if (allocated_offset != static_cast<size_t>(-1)) {
763	                is_reused = true;
764	                DLOG(DEBUG) << "REUSED memory at offset: " << allocated_offset;
765	              } else {
766	                LOG(FATAL) << "Memory allocation failed for: "
767	                           << interval.buffer->name_hint
768	                           << " required: " << interval.size
769	                           << ", new memory available: "
770	                           << (memory_limit_ - next_new_offset_);
771	                continue;
772	              }
773	            }
774	          }
775	
776	          Allocation alloc{interval.buffer, allocated_offset, interval.size,
777	                           is_reused};
778	          allocations.push_back(alloc);
779	          active_allocations.push_back(alloc);
780	          active_queue.push(interval);
781	
782	          if (is_reused) {
783	            removeFromFreeBlocks(allocated_offset, interval.size, free_blocks);
784	          }
785	        }
786	
787	        size_t total_used = next_new_offset_;
788	        size_t reused_count =
789	            std::count_if(allocations.begin(), allocations.end(),
790	                          [](const Allocation &a) { return a.is_reused; });
791	        DLOG(DEBUG) << "Memory usage: " << total_used << "/" << memory_limit_
792	                    << " bytes (" << (total_used * 100.0 / memory_limit_)
793	                    << "%)";
794	        DLOG(DEBUG) << "Reused buffers: " << reused_count << "/"
795	                    << allocations.size();
796	
797	        return allocations;
798	      }
799	
800	    private:
801	      bool CheckConflict(size_t offset, const LiveInterval &current) {
802	        for (const auto &kv : pre_alloc_buffer_) {
803	          const LiveInterval *pre_interval = buffer_map_.at(kv.first);
804	          if (pre_interval->buffer == current.buffer)
805	            continue;
806	
807	          if (current.start < pre_interval->end &&
808	              pre_interval->start < current.end) {
809	            size_t pre_offset = static_cast<size_t>(kv.second);
810	            size_t pre_size = pre_interval->size;
811	            if (offset < pre_offset + pre_size &&
812	                pre_offset < offset + current.size) {
813	              DLOG(DEBUG) << "Buffer " << kv.first->name_hint << " conflict at "
814	                          << pre_offset;
815	              return true;
816	            }
817	          }
818	        }
819	        return false;
820	      }
821	
822	      void
823	      mergeFreeBlocks(std::vector<std::pair<size_t, size_t>> &free_blocks) {
824	        if (free_blocks.empty())
825	          return;
826	
827	        std::sort(free_blocks.begin(), free_blocks.end());
828	
829	        std::vector<std::pair<size_t, size_t>> merged;
830	        merged.push_back(free_blocks[0]);
831	
832	        for (size_t i = 1; i < free_blocks.size(); ++i) {
833	          auto &last = merged.back();
834	          auto &current = free_blocks[i];
835	
836	          if (last.first + last.second >= current.first) {
837	            size_t new_end = std::max(last.first + last.second,
838	                                      current.first + current.second);
839	            last.second = new_end - last.first;
840	          } else {
841	            merged.push_back(current);
842	          }
843	        }
844	
845	        free_blocks = std::move(merged);
846	      }
847	
848	      size_t
849	      findReusableBlock(const LiveInterval &current,
850	                        std::vector<std::pair<size_t, size_t>> &free_blocks) {
851	
852	        std::sort(free_blocks.begin(), free_blocks.end());
853	
854	        for (const auto &block : free_blocks) {
855	          if (block.second >= current.size) {
856	            size_t aligned_offset = AlignUp(block.first, 32);
857	            size_t available_after_align =
858	                block.second - (aligned_offset - block.first);
859	
860	            if (available_after_align >= current.size &&
861	                !CheckConflict(aligned_offset, current)) {
862	              return aligned_offset;
863	            }
864	          }
865	        }
866	
867	        auto &last_block = free_blocks[free_blocks.size() - 1];
868	        if ((last_block.first + last_block.second) == next_new_offset_) {
869	          next_new_offset_ = memory_limit_;
870	          last_block.second = memory_limit_ - last_block.first;
871	          if (last_block.second >= current.size) {
872	            size_t aligned_offset = AlignUp(last_block.first, 32);
873	            size_t available_after_align =
874	                last_block.second - (aligned_offset - last_block.first);
875	
876	            if (available_after_align >= current.size &&
877	                !CheckConflict(aligned_offset, current)) {
878	              return aligned_offset;
879	            }
880	          }
881	        }
882	        return -1;
883	      }
884	
885	      void removeFromFreeBlocks(
886	          size_t offset, size_t size,
887	          std::vector<std::pair<size_t, size_t>> &free_blocks) {
888	        auto it = free_blocks.begin();
889	        while (it != free_blocks.end()) {
890	          if (offset >= it->first && offset < it->first + it->second) {
891	            size_t block_start = it->first;
892	            size_t block_size = it->second;
893	            size_t allocated_end = offset + size;
894	            size_t block_end = block_start + block_size;
895	
896	            it = free_blocks.erase(it);
897	
898	            if (offset > block_start) {
899	              free_blocks.emplace_back(block_start, offset - block_start);
900	            }
901	
902	            if (allocated_end < block_end) {
903	              free_blocks.emplace_back(allocated_end,
904	                                       block_end - allocated_end);
905	            }
906	
907	            break;
908	          } else {
909	            ++it;
910	          }
911	        }
912	      }
913	
914	      size_t memory_limit_;
915	      size_t next_new_offset_;
916	      const std::unordered_map<const VarNode *, int64_t> &pre_alloc_buffer_;
917	      std::unordered_map<const VarNode *, const LiveInterval *> buffer_map_;
918	    };
919	
920	    size_t CalculateBufferSize(const AllocateNode *alloc) {
921	      size_t size_elements = 1;
922	      auto shape_it = external_shape_map_.find(alloc->buffer_var);
923	      if (shape_it != external_shape_map_.end() &&
924	          (*shape_it).second.size() == 4) {
925	        const auto &shape = (*shape_it).second;
926	        const IntImmNode *row = shape[0].as<IntImmNode>();
927	        const IntImmNode *col = shape[1].as<IntImmNode>();
928	        ICHECK(row && col) << "PTO physical buffer shape must be constant";
929	        size_elements = row->value * col->value;
930	      } else {
931	        for (const auto &extent : alloc->extents) {
932	          const IntImmNode *int_imm = extent.as<IntImmNode>();
933	          ICHECK(int_imm) << "Extent must be an integer constant";
934	          size_elements *= int_imm->value;
935	        }
936	      }
937	
938	      size_t size_bytes =
939	          size_elements * alloc->dtype.bytes() * alloc->dtype.lanes();
940	      return AlignUp(size_bytes, 32);
941	    }
942	
943	    void UpdateStmtAttr(const Object *stmt, size_t level) {
944	      stmt_attrs_[stmt] = StmtAttr{level};
945	    }
946	
947	    bool IsNPUSharedMemory(Var buffer_var) {
948	      std::string scope = GetPtrStorageScope(buffer_var);
949	      return memory_limits_.count(scope) > 0;
950	    }
951	
952	    std::unordered_map<const VarNode *, AllocEntry>
953	        alloc_info_; // buffer allocation and level
954	    std::unordered_map<const VarNode *, int64_t>
955	        address_map_; // buffer address map
956	    std::unordered_map<const VarNode *, std::string>
957	        buffer_scopes_; // buffer scope(UB/L1..)
958	    std::unordered_map<const VarNode *, size_t>
959	        buffer_sizes_; // buffer bytes size
960	    // Layout map used to size PTO 4D tiles by physical footprint.
961	    Map<Var, Array<PrimExpr>> external_shape_map_;
962	    std::unordered_map<const VarNode *, size_t>
963	        first_use_; // buffer first use stmt scope
964	    std::unordered_map<std::string, int>
965	        memory_limits_; // buffer scope max limits
966	    std::unordered_map<const Object *, StmtAttr>
967	        stmt_attrs_; // stmt operation level
968	    std::unordered_map<const Object *, EventEntry>
969	        event_map_; // stmt gen/kill event
970	    std::unordered_map<std::string, int64_t>
971	        pre_alloc_buffer_;              // pre alloction buffer address map
972	    std::vector<StmtEntry> linear_seq_; // linear stmt node scopes and levels
973	    std::vector<StmtEntry> scope_;      // temp stmt node scopes and levels
974	    std::vector<const VarNode *> origin_buffer; // original buffer list
975	    std::unordered_set<std::string>
976	        buffer_names_; // buffer names for duplicate check
977	    std::vector<const VarNode *>
978	        tmp_buffers; // temp buffer list for memory planning
979	    std::vector<std::pair<int64_t, int64_t>>
980	        loop_intervals_; // [begin, end] index pairs for each loop
981	    std::unordered_map<const VarNode *, std::set<int64_t>>
982	        buffer_touch_indices_; // buffer -> sorted touch indices
983	
984	    size_t scope_level_{0};
985	    bool memory_auto_plan{false};
986	  };
987	};
988	
989	tvm::transform::Pass AscendMemoryPlanning() {
990	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
991	    auto new_func = AscendMemoryPlanning::Substitute(std::move(f), ctx);
992	    return new_func;
993	  };
994	  return CreatePrimFuncPass(pass_func, 0, "tl.AscendMemoryPlanning", {});
995	}
996	
997	TVM_REGISTER_GLOBAL("tl.transform.AscendMemoryPlanning")
998	    .set_body_typed(AscendMemoryPlanning);
999	
1000	} // namespace tl
1001	} // namespace tvm
