53	namespace tvm {
54	namespace tl {
55	
56	using runtime::StorageRank;
57	using runtime::StorageScope;
58	using namespace tir;
59	
60	/*!
61	 * \brief collect the mapping from the buffer var to its allocate
62	 */
63	class AllocateCollector : public StmtExprVisitor {
64	private:
65	  bool IsDynamicSharedMemory(Var buffer_var) {
66	    StorageScope storage_scope =
67	        runtime::StorageScope::Create(GetPtrStorageScope(buffer_var));
68	    return storage_scope.rank == runtime::StorageRank::kShared &&
69	           storage_scope.tag == ".l1";
70	  }
71	
72	  bool IsStaticSharedMemory(Var buffer_var) {
73	    StorageScope storage_scope =
74	        runtime::StorageScope::Create(GetPtrStorageScope(buffer_var));
75	    return storage_scope.rank == runtime::StorageRank::kShared &&
76	           storage_scope.tag == ".ub";
77	  }
78	
79	public:
80	  void VisitStmt_(const AllocateNode *op) final {
81	    if (IsDynamicSharedMemory(op->buffer_var)) {
82	      dyn_shmem_allocs_[op->buffer_var.get()] = op;
83	    } else if (IsStaticSharedMemory(op->buffer_var)) {
84	      static_shmem_allocs_[op->buffer_var.get()] = op;
85	    }
86	    StmtExprVisitor::VisitStmt_(op);
87	  }
88	  // The dynamic mapping from the original buffer var to its allocate
89	  std::unordered_map<const VarNode *, const AllocateNode *> dyn_shmem_allocs_;
90	  // The static mapping from the original buffer var to its allocate
91	  std::unordered_map<const VarNode *, const AllocateNode *>
92	      static_shmem_allocs_;
93	};
94	
95	// Find a linear pattern of storage access
96	// Used for liveness analysis.
97	// Composite scopes(loop/thread_launch/IfThen) is represented by two points:
98	// before_scope -> scope_body -> after_scope
99	//
100	// The linear_seq_ stores before_scope and after_scope.
101	// The access to the arrays are stored at the after_scope point.
102	//
103	// Define "scope" as the body of For/thread_launch/IfThenElse
104	// This pass tries to detect last point that we need to keep memory
105	// alive under the same scope as allocate.
106	// The storage need to be kept alive between allocate and last access.
107	// The free point is only inserted at the same scope of allocate.
108	//
109	class LinearAccessPatternFinder final : public StmtExprVisitor {
110	public:
111	  /*! \brief record the touch hist of statment. */
112	  struct StmtEntry {
113	    // The statment
114	    const Object *stmt;
115	    // The index in the linear_seq_ to point to end of the nested scope.
116	    // This is only set to non-zero if stmt is a nested scope.
117	    // if offset > 0, means this is the begin, the end entry is current_index +
118	    // offset if offset < 0, means this is the end, the begin entry is
119	    // current_index + offset
120	    int64_t scope_pair_offset{0};
121	    // The buffer variables this statment touched.
122	    std::vector<const VarNode *> touched;
123	  };
124	  // The scope of each allocation
125	  struct AllocEntry {
126	    // The physical dimension of the allocation.
127	    size_t num_physical_dimensions{0};
128	    // scope level
129	    size_t level{0};
130	    // allocation stmt
131	    const AllocateNode *alloc{nullptr};
132	  };
133	
134	  void VisitStmt_(const AllocateNode *op) final {
135	    size_t level = scope_.size();
136	    const VarNode *buf = op->buffer_var.get();
137	
138	    AllocEntry entry;
139	    entry.alloc = op;
140	    entry.level = level;
141	    // Since StorageRewrite occurs after StorageFlatten/FlattenBuffer,
142	    // all allocations specify the extent of physical dimensions, and
143	    // is 1 for flat memory spaces.
144	    entry.num_physical_dimensions = op->extents.size();
145	    alloc_info_[buf] = entry;
146	
147	    StmtExprVisitor::VisitStmt_(op);
148	  }
149	
150	  void VisitStmt_(const BufferStoreNode *op) final {
151	    scope_.push_back(StmtEntry());
152	    // visit subexpr
153	    StmtExprVisitor::VisitStmt_(op);
154	    all_buffers_accessed_.insert(op->buffer.get());
155	
156	    // Add write access.
157	    const VarNode *buffer_var = op->buffer->data.get();
158	    auto it = alloc_info_.find(buffer_var);
159	    if (it != alloc_info_.end() && it->second.alloc) {
160	      ICHECK_LT(it->second.level, scope_.size());
161	      scope_[it->second.level].touched.push_back(buffer_var);
162	
163	      ICHECK_EQ(op->buffer->axis_separators.size() + 1,
164	                it->second.num_physical_dimensions)
165	          << "Buffer " << op->buffer->name << " is allocated with "
166	          << it->second.num_physical_dimensions
167	          << " physical dimensions, but is accessed as having "
168	          << op->buffer->axis_separators.size() + 1 << " physical dimensions"
169	          << std::endl;
170	    }
171	    StmtEntry e = scope_.back();
172	    scope_.pop_back();
173	    if (e.touched.size() != 0) {
174	      e.stmt = op;
175	      linear_seq_.push_back(e);
176	    }
177	  }
178	
179	  void VisitExpr_(const BufferLoadNode *op) final {
180	    // Add write access.
181	    StmtExprVisitor::VisitExpr_(op);
182	
183	    all_buffers_accessed_.insert(op->buffer.get());
184	
185	    const VarNode *buffer_var = op->buffer->data.get();
186	    auto it = alloc_info_.find(buffer_var);
187	    if (it != alloc_info_.end() && it->second.alloc) {
188	      ICHECK_LT(it->second.level, scope_.size())
189	          << "Load memory in places other than store.";
190	      scope_[it->second.level].touched.push_back(buffer_var);
191	
192	      ICHECK_EQ(op->buffer->axis_separators.size() + 1,
193	                it->second.num_physical_dimensions)
194	          << "Buffer " << op->buffer->name << " is allocated with "
195	          << it->second.num_physical_dimensions
196	          << " physical dimensions, but is accessed as having "
197	          << op->buffer->axis_separators.size() + 1 << " physical dimensions"
198	          << std::endl;
199	    }
200	  }
201	
202	  void VisitStmt_(const EvaluateNode *op) final {
203	    scope_.push_back(StmtEntry());
204	    // visit subexpr
205	    StmtExprVisitor::VisitStmt_(op);
206	    StmtEntry e = scope_.back();
207	    scope_.pop_back();
208	    if (e.touched.size() != 0) {
209	      e.stmt = op;
210	      linear_seq_.push_back(e);
211	    }
212	  }
213	
214	  void VisitExpr_(const VarNode *buf) final {
215	    // Directly reference to the variable count as a read.
216	    auto it = alloc_info_.find(buf);
217	    if (it != alloc_info_.end() && it->second.alloc) {
218	      ICHECK_LT(it->second.level, scope_.size()) << " buf=" << buf->name_hint;
219	      scope_[it->second.level].touched.push_back(buf);
220	    }
221	  }
222	
223	  template <typename T> void VisitNewScope(const T *op) {
224	    scope_.push_back(StmtEntry());
225	    StmtEntry e;
226	    e.stmt = op;
227	    int64_t begin_index = static_cast<int64_t>(linear_seq_.size());
228	    // before scope.
229	    linear_seq_.push_back(e);
230	    StmtExprVisitor::VisitStmt_(op);
231	    // after scope.
232	    e.touched = std::move(scope_.back().touched);
233	    scope_.pop_back();
234	    int64_t end_index = static_cast<int64_t>(linear_seq_.size());
235	    ICHECK_GT(end_index, begin_index);
236	    e.scope_pair_offset = begin_index - end_index;
237	    linear_seq_.push_back(e);
238	    // record the pointer to end index.
239	    ICHECK_NE(end_index, 0U);
240	    linear_seq_[begin_index].scope_pair_offset = end_index - begin_index;
241	  }
242	
243	  void VisitStmt_(const AttrStmtNode *op) final {
244	    // Only record the outer most thread extent.
245	    if (op->attr_key == tir::attr::thread_extent && !in_thread_env_) {
246	      in_thread_env_ = true;
247	      VisitNewScope(op);
248	      in_thread_env_ = false;
249	    } else if (op->attr_key == tir::attr::extern_scope) {
250	      VisitNewScope(op);
251	    } else if (op->attr_key == tir::attr::virtual_thread) {
252	      VisitNewScope(op);
253	    } else {
254	      StmtExprVisitor::VisitStmt_(op);
255	    }
256	  }
257	
258	  void VisitStmt_(const IfThenElseNode *op) final { VisitNewScope(op); }
259	
260	  void VisitStmt_(const ForNode *op) final { VisitNewScope(op); }
261	
262	  void VisitStmt_(const WhileNode *op) final { VisitNewScope(op); }
263	
264	  void VisitStmt_(const AssertStmtNode *op) final { VisitNewScope(op); }
265	
266	  void VisitStmt_(const LetStmtNode *op) final { VisitNewScope(op); }
267	
268	  // linearized access sequence.
269	  std::vector<StmtEntry> linear_seq_;
270	  // The storage scope of each buffer
271	  std::unordered_map<const VarNode *, AllocEntry> alloc_info_;
272	  // A record of which Buffer objects have been accessed, to prune
273	  // unused DeclBuffer instances.
274	  std::unordered_set<const BufferNode *> all_buffers_accessed_;
275	
276	private:
277	  // Whether already in thread env.
278	  bool in_thread_env_{false};
279	  // The scope stack.
280	  std::vector<StmtEntry> scope_;
281	};
282	
283	// Verify if the statement can be run safely via inplace fashion
284	//
285	// Detect pattern: dst[index] = f(src[index])
286	//
287	// WARNING: the current detection algorithm cannot handle the case
288	// when a location in an array is written multiple times
289	//
290	// For example, the following program will pass the check,
291	// but we cannot make A and B to be the same array.
292	//
293	//  A[0] = B[0] + 1
294	//  A[0] = B[0] + 1
295	//
296	// The high level code generator needs to ensure that the generated
297	// code only write each location of the target array once.
298	//
299	// This is the case with IR generated by the current compute schedule.
300	// We explicitly return false if we find there is an extern block
301	// which can be arbitrary IR.
302	//
303	// Neve-the-less, inplace detector should be used with care in mind.
304	// We may also consider introduce a condition checker that checks
305	// if every index only visited once for an absolute sufficient condition.
306	//
307	// The code after inplace transformation is no longer idempotent.
308	//
309	class InplaceOpVerifier : public StmtExprVisitor {
310	public:
311	  bool Check(const Object *stmt, const VarNode *dst, const VarNode *src) {
312	    dst_ = dst;
313	    src_ = src;
314	    result_ = true;
315	    if (stmt->IsInstance<AttrStmtNode>()) {
316	      VisitStmt_(static_cast<const AttrStmtNode *>(stmt));
317	    } else if (stmt->IsInstance<ForNode>()) {
318	      VisitStmt_(static_cast<const ForNode *>(stmt));
319	    } else if (stmt->IsInstance<IfThenElseNode>()) {
320	      VisitStmt_(static_cast<const IfThenElseNode *>(stmt));
321	    } else if (stmt->IsInstance<WhileNode>()) {
322	      VisitStmt_(static_cast<const WhileNode *>(stmt));
323	    } else if (stmt->IsInstance<BufferStoreNode>()) {
324	      VisitStmt_(static_cast<const BufferStoreNode *>(stmt));
325	    } else {
326	      return false;
327	    }
328	    return result_;
329	  }
330	
331	  using StmtExprVisitor::VisitStmt_;
332	
333	  void VisitStmt(const Stmt &n) final {
334	    if (!result_)
335	      return;
336	    StmtExprVisitor::VisitStmt(n);
337	  }
338	  void VisitExpr(const PrimExpr &n) final {
339	    if (!result_)
340	      return;
341	    StmtExprVisitor::VisitExpr(n);
342	  }
343	
344	  void VisitExpr_(const VarNode *op) final {
345	    // assume all opaque access is unsafe
346	    if (op == dst_ || op == src_) {
347	      result_ = false;
348	      return;
349	    }
350	  }
351	
352	  void VisitStmt_(const BufferStoreNode *op) final {
353	    ++mem_nest_;
354	    for (const auto &index : op->indices) {
355	      this->VisitExpr(index);
356	    }
357	    --mem_nest_;
358	    if (op->buffer->data.get() == dst_) {
359	      store_ = op;
360	      this->VisitExpr(op->value);
361	      store_ = nullptr;
362	    } else {
363	      this->VisitExpr(op->value);
364	    }
365	  }
366	
367	  void VisitStmt_(const AttrStmtNode *op) final {
368	    // always reject extern code
369	    if (op->attr_key == tir::attr::extern_scope ||
370	        op->attr_key == tir::attr::volatile_scope) {
371	      result_ = false;
372	      return;
373	    }
374	    StmtExprVisitor::VisitStmt_(op);
375	  }
376	
377	  void VisitExpr_(const BufferLoadNode *op) final {
378	    const VarNode *buf = op->buffer->data.get();
379	    // cannot read from dst_ (no reduction)
380	    if (buf == dst_) {
381	      result_ = false;
382	      return;
383	    }
384	    // do not allow indirect memory load
385	    if (mem_nest_ != 0) {
386	      result_ = false;
387	      return;
388	    }
389	    if (src_ == buf) {
390	      if (store_ == nullptr || store_->value.dtype() != op->dtype) {
391	        result_ = false;
392	        return;
393	      }
394	      ICHECK_EQ(store_->indices.size(), op->indices.size())
395	          << "Store/Load occur to the same buffer " << buf->name_hint
396	          << " with differing number of indices";
397	      for (size_t i = 0; i < store_->indices.size(); i++) {
398	        if (!tir::ExprDeepEqual()(store_->indices[i], op->indices[i])) {
399	          result_ = false;
400	          return;
401	        }
402	      }
403	    }
404	    ++mem_nest_;
405	    StmtExprVisitor::VisitExpr_(op);
406	    --mem_nest_;
407	  }
408	
409	private:
410	  // result of the check
411	  bool result_{true};
412	  // destination memory
413	  const VarNode *dst_;
414	  // source variable
415	  const VarNode *src_;
416	  // counter of load,
417	  // it is not safe to inplace when there is nested load like A[B[i]]
418	  int mem_nest_{0};
419	  // The current store to be inspected
420	  const BufferStoreNode *store_{nullptr};
421	};
422	
423	/* \brief Rewrite and merge memory allocation.
424	 *
425	 * Using LinearAccessPatternFinder, determines which buffers could share an
426	 * allocation.  This includes both sequential usage of the same buffer and
427	 * merging small allocations at the same scope into a single larger allocation.
428	 * The merging of small allocations requires the codegen to cast the resulting
429	 * value from the storage type to the output type after access.
430	 */
431	class StoragePlanRewriter : public StmtExprMutator {
432	public:
433	  using StmtEntry = LinearAccessPatternFinder::StmtEntry;
434	  using AllocEntry = LinearAccessPatternFinder::AllocEntry;
435	
436	  Stmt Rewrite(Stmt stmt, bool detect_inplace, bool enable_reuse,
437	               bool reuse_require_exact_matched_dtype,
438	               Map<Var, PrimExpr> local_var_init_map = {}) {
439	    detect_inplace_ = detect_inplace;
440	    local_var_init_map_ = std::move(local_var_init_map);
441	    // plan the rewrite
442	    LinearAccessPatternFinder finder;
443	    finder(stmt);
444	    this->LivenessAnalysis(finder.linear_seq_);
445	    this->PlanMemory(finder.linear_seq_, finder.alloc_info_, enable_reuse,
446	                     reuse_require_exact_matched_dtype);
447	    all_buffers_accessed_ = finder.all_buffers_accessed_;
448	    this->PrepareNewAlloc();
449	    // start rewrite
450	    stmt = operator()(std::move(stmt));
451	    if (attach_map_.count(nullptr)) {
452	      return MakeAttach(attach_map_.at(nullptr), stmt);
453	    }
454	    return stmt;
455	  }
456	
457	  template <typename Node> Node VisitBufferAccess(Node node) {
458	    auto it = alloc_map_.find(node->buffer->data.get());
459	    if (it != alloc_map_.end()) {
460	      Buffer buf = RemapBuffer(node->buffer, it->second->alloc_var);
461	
462	      Array<PrimExpr> indices = node->indices;
463	      indices.Set(indices.size() - 1,
464	                  RemapIndex(node->buffer->dtype, indices[indices.size() - 1],
465	                             it->second));
466	
467	      auto writer = node.CopyOnWrite();
468	      writer->buffer = buf;
469	      writer->indices = indices;
470	    }
471	    return node;
472	  }
473	
474	  Buffer RemapBuffer(Buffer buf, Var new_backing_array) {
475	    auto key = buf.get();
476	    auto it = buffer_remap_.find(key);
477	    if (it != buffer_remap_.end()) {
478	      ICHECK_EQ(it->second->data.get(), new_backing_array.get())
479	          << "Cannot remap buffer " << buf->name << " to use backing array "
480	          << new_backing_array->name_hint << ", previously used backing array "
481	          << it->second->data->name_hint;
482	      return it->second;
483	    }
484	
485	    Buffer remapped = Buffer(
486	        new_backing_array, buf->dtype, buf->shape, buf->strides,
487	        buf->elem_offset, new_backing_array->name_hint, buf->data_alignment,
488	        buf->offset_factor, buf->buffer_type, buf->axis_separators, buf->span);
489	    buffer_remap_[key] = remapped;
490	    return remapped;
491	  }
492	
493	  Stmt VisitStmt_(const BufferStoreNode *op) final {
494	    auto node = Downcast<BufferStore>(StmtExprMutator::VisitStmt_(op));
495	    return VisitBufferAccess(std::move(node));
496	  }
497	
498	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
499	    auto node = Downcast<BufferLoad>(StmtExprMutator::VisitExpr_(op));
500	    return VisitBufferAccess(std::move(node));
501	  }
502	
503	  PrimExpr VisitExpr_(const VarNode *op) final {
504	    auto it = alloc_map_.find(op);
505	    if (it != alloc_map_.end()) {
506	      if (it->second->bits_offset != 0) {
507	        LOG(WARNING)
508	            << "Use a merged buffer variable address, could cause error";
509	      }
510	      return it->second->alloc_var;
511	    } else {
512	      return GetRef<PrimExpr>(op);
513	    }
514	  }
515	  PrimExpr VisitExpr_(const CallNode *op) final {
516	    if (op->op.same_as(builtin::tvm_access_ptr())) {
517	      ICHECK_EQ(op->args.size(), 5U);
518	      DataType dtype = op->args[0].dtype();
519	      const VarNode *buffer = op->args[1].as<VarNode>();
520	      auto it = alloc_map_.find(buffer);
521	      if (it == alloc_map_.end()) {
522	        return StmtExprMutator::VisitExpr_(op);
523	      }
524	      const StorageEntry *se = it->second;
525	      PrimExpr offset = this->VisitExpr(op->args[2]);
526	      PrimExpr extent = this->VisitExpr(op->args[3]);
527	      uint64_t elem_bits = dtype.bits() * dtype.lanes();
528	      ICHECK_EQ(se->bits_offset % elem_bits, 0U);
529	      if (se->bits_offset != 0) {
530	        offset =
531	            make_const(offset.dtype(), se->bits_offset / elem_bits) + offset;
532	      }
533	      return Call(op->dtype, op->op,
534	                  {op->args[0], se->alloc_var, offset, extent, op->args[4]});
535	    } else {
536	      return StmtExprMutator::VisitExpr_(op);
537	    }
538	  }
539	
540	  Stmt VisitStmt_(const AttrStmtNode *op) final {
541	    if (op->attr_key == tir::attr::thread_extent ||
542	        op->attr_key == tir::attr::virtual_thread ||
543	        tir::attr::IsPragmaKey(op->attr_key)) {
544	      // remake all the allocation at the attach scope.
545	      if (attach_map_.count(op)) {
546	        auto &svec = attach_map_[op];
547	        Stmt stmt = StmtExprMutator::VisitStmt_(op);
548	        op = stmt.as<AttrStmtNode>();
549	        return AttrStmt(op->node, op->attr_key, op->value,
550	                        MakeAttach(svec, op->body));
551	      } else {
552	        return StmtExprMutator::VisitStmt_(op);
553	      }
554	    } else if (op->attr_key == tir::attr::volatile_scope) {
555	      Stmt stmt = StmtExprMutator::VisitStmt_(op);
556	      op = stmt.as<AttrStmtNode>();
557	      auto it = alloc_map_.find(op->node.as<VarNode>());
558	      if (it == alloc_map_.end())
559	        return stmt;
560	      return AttrStmt(it->second->alloc_var, op->attr_key, op->value, op->body);
561	    } else {
562	      return StmtExprMutator::VisitStmt_(op);
563	    }
564	  }
565	
566	  Stmt VisitStmt_(const ForNode *op) final {
567	    ICHECK(op->kind != ForKind::kVectorized)
568	        << "VectorizeLoop before LiftStorageAlloc";
569	    // remake all the allocation at the attach scope.
570	    if (attach_map_.count(op)) {
571	      auto &svec = attach_map_[op];
572	      Stmt stmt = StmtExprMutator::VisitStmt_(op);
573	      op = stmt.as<ForNode>();
574	      return For(op->loop_var, op->min, op->extent, op->kind,
575	                 MakeAttach(svec, op->body), op->thread_binding,
576	                 op->annotations);
577	    } else {
578	      return StmtExprMutator::VisitStmt_(op);
579	    }
580	  }
581	
582	  Stmt VisitStmt_(const AllocateNode *op) final {
583	    return this->VisitStmt(op->body);
584	  }
585	
586	  Stmt VisitStmt_(const DeclBufferNode *op) final {
587	    if (hoisted_buffer_decls_.count(op->buffer.get()) ||
588	        !all_buffers_accessed_.count(op->buffer.get())) {
589	      return this->VisitStmt(op->body);
590	    }
591	    auto node = Downcast<DeclBuffer>(StmtExprMutator::VisitStmt_(op));
592	
593	    if (auto it = alloc_map_.find(op->buffer->data.get());
594	        it != alloc_map_.end()) {
595	      Buffer buf = RemapBuffer(op->buffer, it->second->alloc_var);
596	      node.CopyOnWrite()->buffer = buf;
597	    }
598	    return std::move(node);
599	  }
