601	private:
602	  struct StorageEntry {
603	    // The scope that this alloc attaches after
604	    // For shared/local memory it is beginning of the thread extent.
605	    // for global memory it is nullptr, means beginning of everything.
606	    const Object *attach_scope_{nullptr};
607	    // The constant size of the buffer in bits, only used if it is constant
608	    uint64_t const_nbits{0};
609	    // The storage scope.
610	    StorageScope scope;
611	    // The physical dimensionality of the allocations.  Since
612	    // StorageRewrite is applied after StorageFlatten/FlattenBuffer,
613	    // this is size of `AllocateNode::extents`.  If moved
614	    size_t ndim;
615	    // Allocs that shares this entry.
616	    std::vector<const AllocateNode *> allocs;
617	    // The children of this entry, not including itself.
618	    std::vector<StorageEntry *> merged_children;
619	    // The replacement Allocate, if any.  May also include associated
620	    // DeclBuffer statement.
621	    std::vector<Stmt> alloc_nest;
622	    // The var expr of new allocation.
623	    Var alloc_var;
624	    // The allocation element type.
625	    DataType elem_type;
626	    // This is non-zero if this allocate is folded into another one
627	    // the address(in bits) becomes alloc_var + bits_offset;
628	    // can be effectively converted to the element type.
629	    // We need to convert bit_offset to offset of specific element type later.
630	    //
631	    // We use bits(instead of bytes) to support non-conventional indexing in
632	    // hardware. When we are merging buffer together, the bits_offset are set to
633	    // be aligned to certain value given by the max_simd_bits property of the
634	    // special memory.
635	    //
636	    // This allows effective sharing among different types as long as their
637	    // alignment requirement fits into the max_simd_bits.
638	    uint64_t bits_offset{0};
639	  };
640	
641	  // Checks whether the storage_scope is especially tagged for a specific
642	  // memory. Special memory is all combined into a single allocation.
643	  bool IsSpecialTaggedMemory(const StorageScope &scope) {
644	    return scope.tag.length() != 0 && scope.tag != ".l1" &&
645	           scope.tag != ".ub" && scope.tag != ".workspace" &&
646	           scope.tag != ".vtcm";
647	  }
648	
649	  // Alllocate entry of node.
650	  // Event entry in liveness analysis
651	  struct EventEntry {
652	    // variables we generate
653	    std::vector<const VarNode *> gen;
654	    // variables we kill
655	    std::vector<const VarNode *> kill;
656	  };
657	
658	  Stmt MakeAttach(const std::vector<StorageEntry *> &svec, Stmt body) {
659	    for (auto it = svec.rbegin(); it != svec.rend(); it++) {
660	      body = MergeNest((*it)->alloc_nest, body);
661	    }
662	    return body;
663	  }
664	
665	  Map<String, ObjectRef> MakeAllocateAnnotations(const Var &buffer_var) const {
666	    Map<String, ObjectRef> annotations;
667	    if (local_var_init_map_.defined()) {
668	      auto it = local_var_init_map_.find(buffer_var);
669	      if (it != local_var_init_map_.end()) {
670	        const PrimExpr &init = (*it).second;
671	        annotations.Set(tl::attr::kLocalVarInit, init);
672	      }
673	    }
674	    return annotations;
675	  }
676	
677	  // Remap the index
678	  PrimExpr RemapIndex(DataType dtype, PrimExpr index, StorageEntry *e) {
679	    if (e->bits_offset == 0)
680	      return index;
681	    uint64_t elem_bits = dtype.bits();
682	    ICHECK_EQ(e->bits_offset % elem_bits, 0U);
683	    return make_const(index.dtype(), e->bits_offset / elem_bits) + index;
684	  }
685	  // Prepare the new allocations
686	  void PrepareNewAlloc() {
687	    for (size_t i = 0; i < alloc_vec_.size(); ++i) {
688	      StorageEntry *e = alloc_vec_[i].get();
689	      attach_map_[e->attach_scope_].push_back(e);
690	    }
691	    // find allocation via attach map.
692	    for (auto &kv : attach_map_) {
693	      // find the element with the most amount of bytes.
694	      std::vector<StorageEntry *> &vec = kv.second;
695	      // try to find merge, for tagged memory
696	      for (size_t i = 0; i < vec.size(); ++i) {
697	        StorageEntry *e = vec[i];
698	        if (IsSpecialTaggedMemory(e->scope)) {
699	          ICHECK_NE(e->const_nbits, 0U)
700	              << "Special tagged memory must be const size";
701	          for (size_t j = 0; j < i; ++j) {
702	            if (e->scope == vec[j]->scope) {
703	              vec[j]->merged_children.push_back(e);
704	              break;
705	            }
706	          }
707	        }
708	      }
709	      // Start allocation
710	      for (size_t i = 0; i < vec.size(); ++i) {
711	        StorageEntry *e = vec[i];
712	        // already merged
713	        if (e->bits_offset != 0)
714	          continue;
715	        if (e->merged_children.size() != 0) {
716	          NewAllocTagMerged(e);
717	          continue;
718	        }
719	        // Get the allocation size;
720	        e->alloc_var = e->allocs[0]->buffer_var;
721	        DataType alloc_type = e->allocs[0]->dtype;
722	        for (const AllocateNode *op : e->allocs) {
723	          if (op->dtype.lanes() > alloc_type.lanes()) {
724	            alloc_type = op->dtype;
725	          }
726	        }
727	
728	        bool all_allocs_identical = std::all_of(
729	            e->allocs.begin() + 1, e->allocs.end(),
730	            [&](const AllocateNode *op) -> bool {
731	              const AllocateNode *first = *e->allocs.begin();
732	              if (op->dtype != first->dtype) {
733	                return false;
734	              }
735	              if (op->extents.size() != first->extents.size()) {
736	                return false;
737	              }
738	              ExprDeepEqual expr_equal;
739	              for (size_t i = 0; i < op->extents.size(); i++) {
740	                if (!expr_equal(op->extents[i], first->extents[i])) {
741	                  return false;
742	                }
743	              }
744	              return true;
745	            });
746	        if (all_allocs_identical) {
747	          // simply use the original allocation.
748	          Map<String, ObjectRef> annotations =
749	              MakeAllocateAnnotations(e->alloc_var);
750	          e->alloc_nest.push_back(Allocate(
751	              e->alloc_var, alloc_type, e->allocs[0]->extents,
752	              e->allocs[0]->condition, Evaluate(0), std::move(annotations)));
753	
754	          if (auto ptr = e->allocs[0]->body.as<DeclBufferNode>()) {
755	            e->alloc_nest.push_back(DeclBuffer(
756	                RemapBuffer(ptr->buffer, e->alloc_var), Evaluate(0)));
757	            hoisted_buffer_decls_.insert(ptr->buffer.get());
758	          }
759	          if (IsSpecialTaggedMemory(e->scope)) {
760	            MemoryInfo info = GetMemoryInfo(e->scope.to_string());
761	            if (info.defined()) {
762	              uint64_t total_elem = e->const_nbits / e->elem_type.bits();
763	              ICHECK_LE(total_elem * e->elem_type.bits(), info->max_num_bits)
764	                  << "Allocation exceed bound of memory tag "
765	                  << e->scope.to_string();
766	            }
767	          }
768	        } else {
769	          // Build a merged allocation
770	          PrimExpr combo_size;
771	          for (const AllocateNode *op : e->allocs) {
772	            ICHECK_EQ(op->extents.size(), 1)
773	                << "Buffer var " << op->buffer_var->name_hint
774	                << " was identified as a re-usable allocation, but has "
775	                << op->extents.size() << " physical dimensions.  "
776	                << "Currently, only flat 1-d memory spaces should be "
777	                   "identified as re-usable "
778	                   "allocations.";
779	            PrimExpr sz = op->extents[0];
780	            auto nbits = op->dtype.bits() * op->dtype.lanes();
781	            if (const auto *imm = sz.as<IntImmNode>()) {
782	              if (imm->value > std::numeric_limits<int>::max() / nbits) {
783	                LOG(WARNING) << "The allocation requires : " << imm->value
784	                             << " * " << nbits
785	                             << " bits, which is greater than the maximum of"
786	                                " int32. The size is cast to int64."
787	                             << "\n";
788	                sz = make_const(DataType::Int(64), imm->value);
789	              }
790	            }
791	            // transform to bits
792	            auto sz_nbits = sz * nbits;
793	            if (combo_size.defined()) {
794	              combo_size = max(combo_size, sz_nbits);
795	            } else {
796	              combo_size = sz_nbits;
797	            }
798	          }
799	          // transform to alloc bytes
800	          auto type_bits = alloc_type.bits() * alloc_type.lanes();
801	          bool divided =
802	              analyzer_.CanProve(indexmod(combo_size, type_bits) == 0);
803	          combo_size = indexdiv(combo_size, type_bits);
804	          // round up for can not divided
805	          if (!divided) {
806	            combo_size = combo_size + make_const(DataType::Int(32), 1);
807	          }
808	          combo_size = analyzer_.Simplify(combo_size);
809	          Map<String, ObjectRef> annotations =
810	              MakeAllocateAnnotations(e->alloc_var);
811	          e->alloc_nest.push_back(
812	              Allocate(e->alloc_var, alloc_type, {combo_size}, const_true(),
813	                       Evaluate(0), std::move(annotations)));
814	          if (IsSpecialTaggedMemory(e->scope)) {
815	            MemoryInfo info = GetMemoryInfo(e->scope.to_string());
816	            if (info.defined()) {
817	              uint64_t total_elem = e->const_nbits / e->elem_type.bits();
818	              ICHECK_LE(total_elem * e->elem_type.bits(), info->max_num_bits)
819	                  << "Allocation exceed bound of memory tag "
820	                  << e->scope.to_string();
821	            }
822	          }
823	        }
824	      }
825	    }
826	  }
827	  // New allocation for merged data
828	  void NewAllocTagMerged(StorageEntry *e) {
829	    ICHECK_NE(e->scope.tag.length(), 0U);
830	    // allocate with element type.
831	    ICHECK_NE(e->const_nbits, 0U);
832	    MemoryInfo info;
833	    if (e->scope.tag != ".var") {
834	      info = GetMemoryInfo(e->scope.to_string());
835	    }
836	    uint64_t total_bits = e->const_nbits;
837	    // By default, align to 32 bits.
838	    size_t align = 32;
839	    if (info.defined()) {
840	      align = info->max_simd_bits;
841	    }
842	
843	    // Always align to max_simd_bits
844	    // so we can remap types by keeping this property
845	    bool is_var_tag = (e->scope.tag == ".var");
846	    if (!is_var_tag && (total_bits % align != 0)) {
847	      total_bits += align - (total_bits % align);
848	    }
849	
850	    e->alloc_var = e->allocs[0]->buffer_var;
851	    if (!is_var_tag) {
852	      for (StorageEntry *child : e->merged_children) {
853	        ICHECK_NE(child->const_nbits, 0U);
854	        ICHECK_NE(total_bits, 0U);
855	        child->bits_offset = total_bits;
856	        child->alloc_var = e->alloc_var;
857	        total_bits += child->const_nbits;
858	        if (total_bits % align != 0) {
859	          total_bits += align - (total_bits % align);
860	        }
861	      }
862	    }
863	    uint64_t type_bits = e->elem_type.bits() * e->elem_type.lanes();
864	    PrimExpr alloc_size = make_const(e->allocs[0]->extents[0].dtype(),
865	                                     (total_bits + type_bits - 1) / type_bits);
866	    Map<String, ObjectRef> annotations = MakeAllocateAnnotations(e->alloc_var);
867	    e->alloc_nest.push_back(Allocate(e->alloc_var, e->elem_type, {alloc_size},
868	                                     const_true(), Evaluate(0),
869	                                     std::move(annotations)));
870	    if (info.defined()) {
871	      ICHECK_LE(total_bits, info->max_num_bits)
872	          << "Allocation exceed bound of memory tag " << e->scope.to_string();
873	    }
874	  }
875	  // Liveness analysis to find gen and kill point of each variable.
876	  void LivenessAnalysis(const std::vector<StmtEntry> &seq) {
877	    // find kill point, do a reverse linear scan.
878	    std::unordered_set<const VarNode *> touched;
879	    for (size_t i = seq.size(); i != 0; --i) {
880	      const StmtEntry &s = seq[i - 1];
881	      for (const VarNode *buffer : s.touched) {
882	        if (!touched.count(buffer)) {
883	          touched.insert(buffer);
884	          event_map_[s.stmt].kill.push_back(buffer);
885	        }
886	      }
887	    }
888	    // find gen point, do forward scan
889	    touched.clear();
890	    for (size_t i = 0; i < seq.size(); ++i) {
891	      int64_t offset = seq[i].scope_pair_offset;
892	      if (offset < 0)
893	        continue;
894	      const StmtEntry &s = seq[i + offset];
895	      for (const VarNode *buffer : s.touched) {
896	        if (!touched.count(buffer)) {
897	          touched.insert(buffer);
898	          event_map_[s.stmt].gen.push_back(buffer);
899	        }
900	      }
901	    }
902	  }
903	  void PlanNewScope(const Object *op) {
904	    if (thread_scope_ != nullptr) {
905	      ICHECK(thread_scope_ == op);
906	      // erase all memory atatched to this scope.
907	      for (auto it = const_free_map_.begin(); it != const_free_map_.end();) {
908	        if (it->second->attach_scope_ == op) {
909	          it = const_free_map_.erase(it);
910	        } else {
911	          ++it;
912	        }
913	      }
914	      for (auto it = sym_free_list_.begin(); it != sym_free_list_.end();) {
915	        if ((*it)->attach_scope_ == op) {
916	          it = sym_free_list_.erase(it);
917	        } else {
918	          ++it;
919	        }
920	      }
921	      thread_scope_ = nullptr;
922	    } else {
923	      thread_scope_ = op;
924	    }
925	  }
926	
927	  // Memory plan algorithm
928	  void
929	  PlanMemory(const std::vector<StmtEntry> &seq,
930	             const std::unordered_map<const VarNode *, AllocEntry> &alloc_info,
931	             bool enable_reuse, bool reuse_require_exact_matched_dtype) {
932	    std::unordered_set<const VarNode *> inplace_flag;
933	
934	    for (size_t i = 0; i < seq.size(); ++i) {
935	      const StmtEntry &s = seq[i];
936	      auto it = event_map_.find(seq[i].stmt);
937	
938	      // scope_pair_offset >= 0 means it is either
939	      // - leaf stmt(offset = 0)
940	      // - beginning of scope(offset < 0)
941	      // In both cases, we need to handle the gen event correctly
942	      if (it != event_map_.end() && seq[i].scope_pair_offset >= 0) {
943	        // Inplace operation detection
944	        // specially handle this
945	        bool detect_inplace = detect_inplace_ && (it->second.gen.size() <= 2);
946	
947	        for (const VarNode *var : it->second.gen) {
948	          ICHECK(alloc_info.count(var));
949	          const AllocEntry &entry = alloc_info.at(var);
950	          const AllocateNode *alloc = entry.alloc;
951	          auto storage_scope =
952	              StorageScope::Create(GetPtrStorageScope(GetRef<Var>(var)));
953	          StorageEntry *dst_entry = nullptr;
954	          // inplace detection
955	          if (detect_inplace) {
956	            // only one inplace var for s.stmt
957	            bool inplace_found = false;
958	            for (const VarNode *src : it->second.kill) {
959	              if (!inplace_flag.count(src) && alloc_map_.count(src)) {
960	                InplaceOpVerifier visitor;
961	                StorageEntry *src_entry = alloc_map_.at(src);
962	                if (src_entry->scope == storage_scope &&
963	                    src_entry->attach_scope_ == thread_scope_ &&
964	                    src_entry->elem_type == alloc->dtype.element_of() &&
965	                    visitor.Check(s.stmt, var, src)) {
966	                  uint64_t const_nbits =
967	                      static_cast<uint64_t>(alloc->ConstantAllocationSize()) *
968	                      alloc->dtype.bits() * alloc->dtype.lanes();
969	                  if (src_entry->const_nbits == const_nbits && !inplace_found) {
970	                    // successfully inplace
971	                    dst_entry = src_entry;
972	                    inplace_flag.insert(src);
973	                    inplace_found = true;
974	                  }
975	                }
976	              }
977	            }
978	          }
979	          if (dst_entry == nullptr) {
980	            dst_entry = FindAlloc(alloc, thread_scope_, storage_scope,
981	                                  entry.num_physical_dimensions, enable_reuse,
982	                                  reuse_require_exact_matched_dtype);
983	          }
984	          dst_entry->allocs.emplace_back(alloc);
985	          alloc_map_[var] = dst_entry;
986	        }
987	      }
988	      // enter/exit new scope
989	      if (s.stmt->IsInstance<AttrStmtNode>()) {
990	        const auto *op = static_cast<const AttrStmtNode *>(s.stmt);
991	        if (op->attr_key == tir::attr::thread_extent ||
992	            op->attr_key == tir::attr::virtual_thread ||
993	            tir::attr::IsPragmaKey(op->attr_key)) {
994	          PlanNewScope(op);
995	        } else {
996	          ICHECK(op->attr_key == tir::attr::extern_scope);
997	        }
998	      } else if (s.stmt->IsInstance<ForNode>()) {
999	        const auto *op = static_cast<const ForNode *>(s.stmt);
1000	        if (op->kind == ForKind::kParallel) {
1001	          if (thread_scope_ == nullptr || thread_scope_ == op) {
1002	            PlanNewScope(op);
1003	          }
1004	        }
1005	      }
1006	      // scope_pair_offset <= 0 means it is either
1007	      // - leaf stmt(offset = 0)
1008	      // - end of scope(offset < 0)
1009	      // In both cases, we need to handle the kill event correctly
1010	      if (it != event_map_.end() && seq[i].scope_pair_offset <= 0) {
1011	        for (const VarNode *var : it->second.kill) {
1012	          // skip space which are already replaced by inplace
1013	          if (!inplace_flag.count(var)) {
1014	            this->Free(var);
1015	          }
1016	        }
1017	      }
1018	    }
1019	  }
1020	  // Allocate new storage entry.
1021	  StorageEntry *NewAlloc(const AllocateNode *op, const Object *attach_scope,
1022	                         const StorageScope &scope, size_t const_nbits) {
1023	    ICHECK(op != nullptr);
1024	    // Re-use not successful, allocate a new buffer.
1025	    auto entry = std::make_unique<StorageEntry>();
1026	    entry->attach_scope_ = attach_scope;
1027	    entry->scope = scope;
1028	    entry->elem_type = op->dtype.element_of();
1029	    entry->const_nbits = const_nbits;
1030	    StorageEntry *e = entry.get();
1031	    alloc_vec_.emplace_back(std::move(entry));
1032	    return e;
1033	  }
1034	
1035	  StorageEntry *FindAlloc(const AllocateNode *op, const Object *attach_scope,
1036	                          const StorageScope &scope,
1037	                          size_t num_physical_dimensions, bool enable_reuse,
1038	                          bool reuse_require_exact_matched_dtype) {
1039	    ICHECK(op != nullptr);
1040	    // skip plan for local variable,
1041	    // compiler can do a better job with register allocation.
1042	    const uint64_t match_range = 16;
1043	    uint64_t op_elem_bits = op->dtype.bits() * op->dtype.lanes();
1044	    uint64_t const_nbits =
1045	        static_cast<uint64_t>(op->ConstantAllocationSize() * op_elem_bits);
1046	
1047	    // If the size of the array isn't known at compile-time, it must
1048	    // have its own allocation with size determined at runtime.
1049	    bool is_known_size = (const_nbits != 0);
1050	
1051	    // Currently, only flat memory spaces can be re-used.  Packing
1052	    // into N-d space (e.g. 2-d texture memory on GPUs) will require
1053	    // more in-depth algorithms.
1054	    bool is_flat_memory_space = (num_physical_dimensions == 1);
1055	
1056	    // disable reuse of small arrays, they will be lowered to registers in LLVM
1057	    // This rules only apply if we are using non special memory
1058	    bool is_small_array =
1059	        (scope.tag.length() == 0 || scope.tag == ".ub") &&
1060	        (scope.rank >= StorageRank::kWarp || op->dtype.is_handle() ||
1061	         (is_known_size && const_nbits <= 32));
1062	
1063	    if (!enable_reuse || is_small_array || !is_flat_memory_space) {
1064	      return NewAlloc(op, attach_scope, scope, const_nbits);
1065	    }
1066	
1067	    if (is_known_size) {
1068	      // constant allocation.
1069	      auto begin = const_free_map_.lower_bound(const_nbits / match_range);
1070	      auto mid = const_free_map_.lower_bound(const_nbits);
1071	      auto end = const_free_map_.upper_bound(const_nbits * match_range);
1072	      // start looking at the buffer that is bigger than the required size first
1073	      for (auto it = mid; it != end; ++it) {
1074	        StorageEntry *e = it->second;
1075	        if (e->attach_scope_ != attach_scope)
1076	          continue;
1077	        if (e->scope != scope)
1078	          continue;
1079	        // when not divided, no reuse, eg, float4 vs float3
1080	        if (e->bits_offset % op_elem_bits != 0)
1081	          continue;
1082	        if (reuse_require_exact_matched_dtype && e->elem_type != op->dtype) {
1083	          continue;
1084	        }
1085	        e->const_nbits = std::max(const_nbits, e->const_nbits);
1086	        const_free_map_.erase(it);
1087	        return e;
1088	      }
1089	      // then start looking at smaller buffers.
1090	      for (auto it = mid; it != begin;) {
1091	        --it;
1092	        StorageEntry *e = it->second;
1093	        if (e->attach_scope_ != attach_scope)
1094	          continue;
1095	        if (e->scope != scope)
1096	          continue;
1097	        if (e->elem_type != op->dtype.element_of())
1098	          continue;
1099	        if (reuse_require_exact_matched_dtype && e->elem_type != op->dtype) {
1100	          continue;
1101	        }
1102	        e->const_nbits = std::max(const_nbits, e->const_nbits);
1103	        const_free_map_.erase(it);
1104	        return e;
1105	      }
1106	    } else {
1107	      // Simple strategy: round roubin.
1108	      for (auto it = sym_free_list_.begin(); it != sym_free_list_.end(); ++it) {
1109	        StorageEntry *e = *it;
1110	        if (e->attach_scope_ != attach_scope)
1111	          continue;
1112	        if (e->scope != scope)
1113	          continue;
1114	        if (e->elem_type != op->dtype.element_of())
1115	          continue;
1116	        sym_free_list_.erase(it);
1117	        return e;
1118	      }
1119	    }
1120	    return NewAlloc(op, attach_scope, scope, const_nbits);
1121	  }
1122	  // simulated free.
1123	  void Free(const VarNode *var) {
1124	    auto it = alloc_map_.find(var);
1125	    ICHECK(it != alloc_map_.end());
1126	    StorageEntry *e = it->second;
1127	    ICHECK_NE(e->allocs.size(), 0U);
1128	
1129	    // disable reuse of small arrays, they will be lowered to registers in LLVM
1130	    // This rules only apply if we are using non special memory
1131	    if (e->scope.tag.length() == 0 || e->scope.tag == ".ub") {
1132	      // Disable sharing of local memory.
1133	      if (e->scope.rank >= StorageRank::kWarp ||
1134	          e->allocs[0]->dtype.is_handle())
1135	        return;
1136	      // disable reuse of small arrays
1137	      if (e->const_nbits > 0 && e->const_nbits <= 32)
1138	        return;
1139	    }
1140	    // normal free.
1141	    if (e->const_nbits != 0) {
1142	      const_free_map_.insert({e->const_nbits, e});
1143	    } else {
1144	      sym_free_list_.push_back(e);
1145	    }
1146	  }
1147	  // thread scope.
1148	  const Object *thread_scope_{nullptr};
1149	  // whether enable inplace detection.
1150	  bool detect_inplace_{false};
1151	  // Locations of free ops.
1152	  std::unordered_map<const Object *, EventEntry> event_map_;
1153	  // constant size free map.
1154	  std::multimap<uint64_t, StorageEntry *> const_free_map_;
1155	  // symbolic free list, for non constant items.
1156	  std::list<StorageEntry *> sym_free_list_;
1157	  // The allocation attach map
1158	  std::unordered_map<const Object *, std::vector<StorageEntry *>> attach_map_;
1159	  // The allocation assign map
1160	  std::unordered_map<const VarNode *, StorageEntry *> alloc_map_;
1161	  // The allocations
1162	  std::vector<std::unique_ptr<StorageEntry>> alloc_vec_;
1163	  // The buffer objects being remapped
1164	  std::unordered_map<const BufferNode *, Buffer> buffer_remap_;
1165	  // Buffers whose DeclBuffer has been hoisted to be adjacent to the new
1166	  // Allocate location
1167	  std::unordered_set<const BufferNode *> hoisted_buffer_decls_;
1168	  // Any buffers that is accessed at some point.  DeclBuffer instances
1169	  // that do not appear in this list may be removed.
1170	  std::unordered_set<const BufferNode *> all_buffers_accessed_;
1171	  // Initial values for local variable buffers.
1172	  Map<Var, PrimExpr> local_var_init_map_;
1173	  // analyzer
1174	  arith::Analyzer analyzer_;
1175	};
