1177	/* Helper struct containing information on how a buffer is declared and used
1178	 *
1179	 */
1180	struct BufferVarInfo {
1181	  enum DeclarationLocation {
1182	    kPrimFuncParam = (1 << 0),
1183	    kPrimFuncBufferMap = (1 << 1),
1184	    kAllocateNode = (1 << 2),
1185	    kAllocateConstNode = (1 << 3),
1186	    kLetNode = (1 << 4),
1187	  };
1188	
1189	  // The tir::Var that represents this buffer.
1190	  Var var;
1191	
1192	  // The data type of an element of the buffer.
1193	  DataType element_dtype;
1194	
1195	  /* The extent of the buffer.
1196	   *
1197	   * If multidimensional, the extent of the last dimension of the buffer.  If
1198	   * the size is unknown (e.g. pointer arguments to PrimFunc with no
1199	   * corresponding entry in buffer_map), then extent is zero.
1200	   */
1201	  PrimExpr extent;
1202	
1203	  // Where the buffer was declared
1204	  DeclarationLocation declaration_location;
1205	
1206	  // When accessed, which element type is it accessed as.  This may
1207	  // differ both in base type (e.g. int32* cast to float32* after
1208	  // packing in StorageRewrite) or in number of lanes (e.g. float16*
1209	  // cast to float16x4*).
1210	  std::unordered_set<DataType> access_dtype;
1211	  // Data types used for scalar reads. This is used to record vectorized read
1212	  // dtypes that can be shuffled for scalar reads when
1213	  // rewrite_scalar_read_to_vector_shuffle is enabled.
1214	  std::unordered_set<DataType> scalar_read_dtype;
1215	
1216	  DataType get_preferred_dtype() const {
1217	    std::unordered_set<DataType> base_access_dtype;
1218	    for (auto dtype : access_dtype) {
1219	      base_access_dtype.insert(dtype.element_of());
1220	    }
1221	    for (auto dtype : scalar_read_dtype) {
1222	      base_access_dtype.insert(dtype.element_of());
1223	    }
1224	    // If the array is accessed as multiple base types within a
1225	    // function, no point in changing the declared type.  CodeGenC can
1226	    // handle this with a type-cast prior to indexing.  Vulkan will
1227	    // raise an error at code-gen time, if a later pass doesn't split
1228	    // it out.
1229	    if (base_access_dtype.size() != 1) {
1230	      return element_dtype;
1231	    }
1232	
1233	    DataType preferred_base_type = *base_access_dtype.begin();
1234	
1235	    // If there is only one vectorizable size used to access the
1236	    // buffer, and if that access size is compatible with the array
1237	    // size, then the buffer is vectorizable.  In the future, this
1238	    // could be improved to allow vectorized buffer access of size
1239	    // GCD(*lanes_used), if necessary.
1240	    // When there are scalar reads and no writes, access_dtype can be empty and
1241	    // we should avoid rewriting.
1242	    int preferred_lanes = element_dtype.lanes();
1243	    if (element_dtype.lanes() == 1 && (access_dtype.size() == 1)) {
1244	      int lanes = access_dtype.begin()->lanes();
1245	      // Check the scalar read dtypes are compatible with the vectorized access
1246	      // dtype.
1247	      for (auto dtype : scalar_read_dtype) {
1248	        if (dtype.lanes() % lanes != 0) {
1249	          return element_dtype;
1250	        }
1251	      }
1252	      arith::Analyzer analyzer_;
1253	      arith::ModularSet me = analyzer_.modular_set(extent);
1254	      if ((me->coeff % lanes == 0) && (me->base % lanes == 0)) {
1255	        preferred_lanes = lanes;
1256	      }
1257	    }
1258	
1259	    return preferred_base_type.with_lanes(preferred_lanes);
1260	  }
1261	};
