1263	/* Checks whether buffers are accessed as scalar or vector parameters in a
1264	 * function.
1265	 *
1266	 */
1267	class VectorTypeAccessChecker : public StmtExprVisitor {
1268	public:
1269	  /* Constructor
1270	   *
1271	   * @param params The parameters passed to a PrimFunc
1272	   *
1273	   * @param buffer_map The buffer_map associated with a PrimFunc
1274	   *
1275	   * @param allow_untyped_handles If a buffer or pointer variable is
1276	   * missing a type annotation, assume that it has the same underlying
1277	   * type as it is later accessed, with scalar element types.
1278	   */
1279	  VectorTypeAccessChecker(const Array<tir::Var> &params,
1280	                          const Map<Var, Buffer> &buffer_map,
1281	                          bool allow_untyped_pointers = false,
1282	                          bool detect_scalar_read_patterns = true)
1283	      : allow_untyped_pointers_(allow_untyped_pointers),
1284	        detect_scalar_read_patterns_(detect_scalar_read_patterns) {
1285	    // If a parameter is in the buffer map, we want to track the
1286	    // version in the map.
1287	    for (auto it : buffer_map) {
1288	      Buffer &buffer = it.second;
1289	      Var buffer_var = buffer->data;
1290	      DataType dtype = buffer->dtype;
1291	      PrimExpr extent =
1292	          buffer->shape.size() ? buffer->shape[buffer->shape.size() - 1] : 0;
1293	      OnArrayDeclaration(buffer_var, dtype, extent,
1294	                         BufferVarInfo::kPrimFuncParam);
1295	    }
1296	
1297	    // If a pointer parameter isn't in the buffer map, then we want to
1298	    // track the parameter itself.
1299	    for (Var buffer_var : params) {
1300	      auto pointer_type = GetPointerType(buffer_var->type_annotation);
1301	      if (pointer_type.has_value() && (buffer_map.count(buffer_var) == 0)) {
1302	        DataType dtype = pointer_type.value();
1303	        PrimExpr extent = 0;
1304	        OnArrayDeclaration(buffer_var, dtype, extent,
1305	                           BufferVarInfo::kPrimFuncBufferMap);
1306	      }
1307	    }
1308	  }
1309	
1310	  void VisitExpr_(const BufferLoadNode *op) final {
1311	    OnArrayAccess(op->dtype, op->buffer->data.get(), op->indices,
1312	                  /*is_buffer_load=*/true);
1313	    StmtExprVisitor::VisitExpr_(op);
1314	  }
1315	
1316	  void VisitStmt_(const BufferStoreNode *op) final {
1317	    OnArrayAccess(op->value.dtype(), op->buffer->data.get(), op->indices,
1318	                  /*is_buffer_load=*/false);
1319	    StmtExprVisitor::VisitStmt_(op);
1320	  }
1321	
1322	  void VisitExpr_(const CallNode *op) final {
1323	    if (op->op.same_as(builtin::tvm_access_ptr())) {
1324	      DataType dtype = op->args[0].dtype();
1325	      const VarNode *buffer = op->args[1].as<VarNode>();
1326	      PrimExpr index = op->args[2];
1327	      OnArrayAccess(dtype, buffer, {index}, false);
1328	    } else if (op->op.same_as(builtin::address_of())) {
1329	      if (auto load = op->args[0].as<BufferLoadNode>()) {
1330	        OnArrayAccess(load->dtype, load->buffer->data.get(), load->indices,
1331	                      /*is_buffer_load=*/false);
1332	      }
1333	    }
1334	    StmtExprVisitor::VisitExpr_(op);
1335	  }
1336	
1337	  void VisitStmt_(const AllocateNode *op) final {
1338	    const Array<PrimExpr> &extents = op->extents;
1339	    PrimExpr extent = extents[extents.size() - 1];
1340	    OnArrayDeclaration(op->buffer_var, op->dtype, extent,
1341	                       BufferVarInfo::kAllocateNode);
1342	
1343	    StmtExprVisitor::VisitStmt_(op);
1344	  }
1345	
1346	  void VisitStmt_(const AllocateConstNode *op) final {
1347	    const Array<PrimExpr> &extents = op->extents;
1348	    PrimExpr extent =
1349	        extents.size() ? extents[extents.size() - 1] : NullValue<PrimExpr>();
1350	    OnArrayDeclaration(op->buffer_var, op->dtype, extent,
1351	                       BufferVarInfo::kAllocateConstNode);
1352	
1353	    StmtExprVisitor::VisitStmt_(op);
1354	  }
1355	
1356	  void VisitExpr_(const LetNode *op) final {
1357	    HandleLetNode(op->var);
1358	    StmtExprVisitor::VisitExpr_(op);
1359	  }
1360	
1361	  void VisitStmt_(const LetStmtNode *op) final {
1362	    HandleLetNode(op->var);
1363	    StmtExprVisitor::VisitStmt_(op);
1364	  }
1365	
1366	  void HandleLetNode(Var let_var) {
1367	    if (let_var->dtype.is_handle()) {
1368	      auto pointer_type = GetPointerType(let_var->type_annotation);
1369	      if (pointer_type.has_value()) {
1370	        OnArrayDeclaration(let_var, pointer_type.value(), 0,
1371	                           BufferVarInfo::kLetNode);
1372	      } else if (allow_untyped_pointers_) {
1373	        OnArrayDeclaration(let_var, let_var->dtype, 0, BufferVarInfo::kLetNode);
1374	      } else {
1375	        LOG(FATAL) << "Let statement of variable " << let_var->name_hint
1376	                   << " is missing a type annotation, "
1377	                   << "or type annotation is not a pointer to primitive";
1378	      }
1379	    }
1380	  }
1381	
1382	  /* Update the type map for a buffer based on its declaration
1383	   *
1384	   * @param buffer The VarNode representing the buffer.
1385	   *
1386	   * @param element_dtype The dtype of a single element of the buffer.
1387	   * If unknown, when used with the allow_untyped_handles option,
1388	   * should be a handle dtype.
1389	   *
1390	   * @param extent The extent of the buffer.  Zero if size is unknown.
1391	   *
1392	   * @param declaration_location How the buffer was allocated, so that
1393	   * some locations can be rewritten without others.
1394	   */
1395	  void
1396	  OnArrayDeclaration(Var buffer, DataType element_dtype, PrimExpr extent,
1397	                     BufferVarInfo::DeclarationLocation declaration_location) {
1398	    ICHECK(info_map_.find(buffer.get()) == info_map_.end())
1399	        << "Array declaration of " << buffer->name_hint
1400	        << " occurred multiple times.";
1401	
1402	    if (element_dtype == DataType::Bool()) {
1403	      element_dtype = DataType::Int(8).with_lanes(element_dtype.lanes());
1404	    }
1405	    info_map_[buffer.get()] =
1406	        BufferVarInfo{buffer, element_dtype, extent, declaration_location};
1407	  }
1408	
1409	  /* Update the type map for a buffer based on its usage
1410	   *
1411	   * @param value_dtype The dtype of the value being stored to or
1412	   * loaded from the buffer.
1413	   *
1414	   * @param buffer The VarNode representing the buffer.
1415	   *
1416	   * @param indices The index at which the value is being stored/loaded.
1417	   *
1418	   * @param is_buffer_load Whether the access is BufferLoad
1419	   */
1420	  void OnArrayAccess(DataType value_dtype, const VarNode *buffer,
1421	                     const Array<PrimExpr> &indices, bool is_buffer_load) {
1422	    auto it = info_map_.find(buffer);
1423	    ICHECK(it != info_map_.end())
1424	        << "Load/Store of buffer " << buffer->name_hint << " (" << buffer
1425	        << ") occurred before its declaration.";
1426	
1427	    if (value_dtype.is_scalable_vector()) {
1428	      // Scalable types are not currently supported in storage_rewrite. Scalable
1429	      // buffer accesses are not currently checked and therefore are not
1430	      // rewritten.
1431	      return;
1432	    }
1433	
1434	    BufferVarInfo &var_info = it->second;
1435	
1436	    if (value_dtype.element_of() == DataType::Bool()) {
1437	      value_dtype = DataType::Int(8).with_lanes(value_dtype.lanes());
1438	    }
1439	
1440	    if (var_info.element_dtype.is_handle()) {
1441	      ICHECK(allow_untyped_pointers_)
1442	          << "Variable " << buffer->name_hint
1443	          << " was missing a type annotation in its declaration";
1444	      var_info.element_dtype = value_dtype.element_of();
1445	    }
1446	
1447	    for (int i = 0; i < static_cast<int>(indices.size()) - 1; i++) {
1448	      ICHECK(indices[i].dtype().is_scalar())
1449	          << "Only the last index of a buffer access may be a vector type.";
1450	    }
1451	    int index_lanes = indices.size() ? indices.back().dtype().lanes() : 1;
1452	
1453	    DataType access_dtype = value_dtype;
1454	
1455	    int lanes_used = var_info.element_dtype.lanes();
1456	
1457	    // This can happen due to a previous pass that had rewrite_store_load =
1458	    // false.  This occurs from the StorageRewrite in tvm::lower, followed by
1459	    // the PointerValueTypeRewrite in BuildSPIRV.  The rewrite_store_load =
1460	    // false is necessary because the C-based codegens do not yet support
1461	    // vectorized pointer types (e.g. float16x4*).  Once they do, this if
1462	    // statement should instead be replaced by the below ICHECK_EQ.
1463	    if (index_lanes * var_info.element_dtype.lanes() != value_dtype.lanes()) {
1464	      if (index_lanes > 1 && value_dtype.lanes() == 1) {
1465	        lanes_used = 1;
1466	      } else {
1467	        ICHECK_EQ(index_lanes, value_dtype.lanes());
1468	        lanes_used = 1;
1469	        var_info.element_dtype = var_info.element_dtype.with_lanes(1);
1470	      }
1471	    }
1472	
1473	    // TODO(Lunderberg): Uncomment this check once it can be applied.
1474	    // See https://discuss.tvm.apache.org/t/pre-rfc-vectorized-tir-buffers/10615
1475	    // for discussion.
1476	
1477	    // ICHECK_EQ(index_lanes * var_info.element_dtype.lanes(),
1478	    // value_dtype.lanes())
1479	    //     << "Attempting to retrieve " << value_dtype.lanes() << " lanes of
1480	    //     data with "
1481	    //     << index_lanes << " indices into an array whose elements have "
1482	    //     << var_info.element_dtype.lanes() << " lanes.  "
1483	    //     << "Expected output with " << index_lanes *
1484	    //     var_info.element_dtype.lanes()
1485	    //     << " lanes.";
1486	
1487	    // If the index is a RampNode with stride of 1 and offset
1488	    // divisible by the number of number of lanes, and the predicate
1489	    // does not apply any masking, then this array access could be
1490	    // vectorized.
1491	    if (indices.size()) {
1492	      const RampNode *ramp_index = indices[indices.size() - 1].as<RampNode>();
1493	      if (ramp_index && is_one(ramp_index->stride)) {
1494	        if (ramp_index->lanes->IsInstance<IntImmNode>()) {
1495	          int lanes =
1496	              static_cast<int>(Downcast<IntImm>(ramp_index->lanes)->value);
1497	          arith::ModularSet me = analyzer_.modular_set(ramp_index->base);
1498	          if ((me->coeff % lanes == 0) && (me->base % lanes == 0)) {
1499	            lanes_used = lanes;
1500	          }
1501	        }
1502	      }
1503	    }
1504	
1505	    if (detect_scalar_read_patterns_ && is_buffer_load && indices.size()) {
1506	      const PrimExpr last_dim_index = indices[indices.size() - 1];
1507	      if (last_dim_index.dtype().lanes() == 1) {
1508	        arith::ModularSet me = analyzer_.modular_set(last_dim_index);
1509	        var_info.scalar_read_dtype.emplace(access_dtype.with_lanes(me->coeff));
1510	        return;
1511	      }
1512	    }
1513	    var_info.access_dtype.insert(access_dtype.with_lanes(lanes_used));
1514	  }
1515	
1516	  // Map of buffer variable information determined
1517	  std::unordered_map<const VarNode *, BufferVarInfo> info_map_;
1518	
1519	  //
1520	  bool allow_untyped_pointers_{false};
1521	  // Whether to detect scalar read patterns for rewriting to vector shuffle
1522	  bool detect_scalar_read_patterns_{true};
1523	
1524	  // internal analyzer
1525	  arith::Analyzer analyzer_;
1526	};
