1528	/* \brief Rewrites buffer/pointer variables from scalar types to vectorized
1529	 * types.
1530	 *
1531	 * Some runtimes do not allow casting between composite types and the underlying
1532	 * base type (e.g. Vulkan, casting from 1-lane float16* to 4-lane float16x4*).
1533	 * In these cases, in order to have vectorized load/store on an array, the
1534	 * element type of that array must be vectorized.  This is in contrast to
1535	 * C-style runtimes, in which `float16x4* vec = *(float16x4*)(float_arr +
1536	 * offset)` is valid.
1537	 *
1538	 * By default, VectorTypeRewriter will attempt to rewrite all buffer variables
1539	 * to vectorized access, if the load/store occurring in the PrimFunc are all
1540	 * vectorized.  This includes adjusting the indices being used to access the
1541	 * array.  (e.g. If `float16* scalar_arr` is being converted to `float16x4*
1542	 * vec_arr`, then `scalar_arr[Ramp(offset, 1, 4)]` will be converted to
1543	 * `vec_arr[offset/4]`.)
1544	 *
1545	 * Currently, several of the C-style runtimes do not support buffers whose
1546	 * elements are vectorized types, or rely on the presence of the Ramp nodes to
1547	 * identify vectorized loads.  The boolean parameters in the constructor are to
1548	 * mimic the previous behavior of VectorTypeRewriter, to avoid breaking these
1549	 * runtimes.  Once all runtimes support vectorized buffer elements, these
1550	 * parameters can be removed.
1551	 */
1552	class VectorTypeRewriter : public StmtExprMutator {
1553	public:
1554	  /* Constructor
1555	   *
1556	   * @param checker The VectorTypeAccessChecker that has previously read out
1557	   * information from the PrimFunc
1558	   *
1559	   * @param rewrite_params Whether pointer-type parameters passed into the
1560	   * function should be rewritten from scalar types to vectorized types.
1561	   *
1562	   * @param rewrite_buffer_map Whether buffers present in the buffer_map should
1563	   * have their data variable be rewritten from scalar types to vectorized
1564	   * types.
1565	   *
1566	   * @param rewrite_allocate_node Whether the buffer variable associated with
1567	   * AllocateNodes should be rewritten from scalar types to vectorized types.
1568	   *
1569	   * @param rewrite_indices Whether the indices to the Load and Store nodes
1570	   * should be rewritten to correspond to the new buffer_var type.
1571	   *
1572	   * @param rewrite_let_node Whether pointer declarations in let nodes
1573	   * should be re-written.
1574	   */
1575	  VectorTypeRewriter(
1576	      const std::unordered_map<const VarNode *, BufferVarInfo> &info_map,
1577	      bool rewrite_params = true, bool rewrite_buffer_map = true,
1578	      bool rewrite_allocate_node = true, bool rewrite_indices = true,
1579	      bool rewrite_let_node = true, bool rewrite_allocate_const_node = true,
1580	      bool rewrite_scalar_read_to_vector_shuffle = true)
1581	      : rewrite_indices_(rewrite_indices) {
1582	    int rewrite_mask = 0;
1583	    if (rewrite_params) {
1584	      rewrite_mask |= BufferVarInfo::kPrimFuncParam;
1585	    }
1586	    if (rewrite_buffer_map) {
1587	      rewrite_mask |= BufferVarInfo::kPrimFuncBufferMap;
1588	    }
1589	    if (rewrite_allocate_node) {
1590	      rewrite_mask |= BufferVarInfo::kAllocateNode;
1591	    }
1592	    if (rewrite_let_node) {
1593	      rewrite_mask |= BufferVarInfo::kLetNode;
1594	    }
1595	    if (rewrite_allocate_const_node) {
1596	      rewrite_mask |= BufferVarInfo::kAllocateConstNode;
1597	    }
1598	
1599	    // Rewrite any buffer variables whose preferred type isn't their current
1600	    // type.
1601	    for (const auto &pair : info_map) {
1602	      const auto &var_info = pair.second;
1603	      DataType preferred = var_info.get_preferred_dtype();
1604	      if (preferred != var_info.element_dtype &&
1605	          (rewrite_mask & var_info.declaration_location)) {
1606	        Var old_buffer_var = var_info.var;
1607	        Var new_buffer_var(old_buffer_var->name_hint,
1608	                           PointerType(PrimType(preferred),
1609	                                       GetPtrStorageScope(old_buffer_var)),
1610	                           old_buffer_var->span);
1611	
1612	        rewrite_map_[var_info.var.get()] = {var_info.var, new_buffer_var,
1613	                                            var_info.element_dtype, preferred};
1614	      }
1615	    }
1616	  }
1617	
1618	  /*!
1619	   * \brief Mutator for BufferLoad or BufferStore.
1620	   * \return The rewritten node and the shuffle index. (Only for BufferLoad)
1621	   * When the shuffle index is non-negative, the caller should generate Shuffle
1622	   * to extract the element from the vector.
1623	   */
1624	  template <typename Node> std::pair<Node, int> VisitBufferAccess(Node node) {
1625	    int shuffle_index = -1;
1626	    if (!rewrite_indices_) {
1627	      return {node, shuffle_index};
1628	    }
1629	
1630	    auto it = rewrite_map_.find(node->buffer->data.get());
1631	    if (it == rewrite_map_.end()) {
1632	      return {node, shuffle_index};
1633	    }
1634	    const auto &info = it->second;
1635	
1636	    Array<PrimExpr> indices = node->indices;
1637	    const PrimExpr &last_dim_index = indices[indices.size() - 1];
1638	    const RampNode *ramp_index = indices[indices.size() - 1].as<RampNode>();
1639	
1640	    if (node->buffer->dtype.is_scalable_vector() ||
1641	        last_dim_index.dtype().is_scalable_vector()) {
1642	      // Scalable types are not currently supported in storage_rewrite. Scalable
1643	      // buffer accesses are not currently checked and therefore are not
1644	      // rewritten.
1645	      return {node, shuffle_index};
1646	    }
1647	
1648	    if (ramp_index && is_one(ramp_index->stride) &&
1649	        ramp_index->lanes->IsInstance<IntImmNode>()) {
1650	      int lanes = static_cast<int>(Downcast<IntImm>(ramp_index->lanes)->value);
1651	      PrimExpr new_index =
1652	          ramp_index->base / make_const(ramp_index->base.dtype(), lanes);
1653	      if (lanes != info.factor()) {
1654	        ICHECK(info.factor() && lanes % info.factor() == 0);
1655	        int new_lanes = lanes / info.factor();
1656	        new_index = Ramp(new_index * new_lanes, ramp_index->stride, new_lanes,
1657	                         ramp_index->span);
1658	      }
1659	      indices.Set(indices.size() - 1, new_index);
1660	    } else if (last_dim_index.dtype().lanes() == 1 && info.factor() > 1) {
1661	      arith::ModularSet me = analyzer_.modular_set(last_dim_index);
1662	      ICHECK(me->coeff == 0 || info.factor() % me->coeff == 0);
1663	      PrimExpr new_index =
1664	          last_dim_index / make_const(last_dim_index.dtype(), info.factor());
1665	      shuffle_index = me->base;
1666	      indices.Set(indices.size() - 1, new_index);
1667	    }
1668	
1669	    auto writer = node.CopyOnWrite();
1670	    writer->buffer = RemapBuffer(node->buffer);
1671	    writer->indices = indices;
1672	    return {node, shuffle_index};
1673	  }
1674	
1675	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
1676	    auto node = Downcast<BufferLoad>(StmtExprMutator::VisitExpr_(op));
1677	    auto [modified, shuffle_index] = VisitBufferAccess(node);
1678	
1679	    // Not needed for BufferStoreNode, so we can't just call
1680	    // LegalizeDtype() in VisitBufferAccess.
1681	    if (node.same_as(modified)) {
1682	      return std::move(node);
1683	    } else {
1684	      BufferLoad legalized_modified(modified->buffer, modified->indices,
1685	                                    modified->span);
1686	      if (shuffle_index >= 0) {
1687	        return Shuffle::ExtractElement(std::move(legalized_modified),
1688	                                       shuffle_index);
1689	      }
1690	      return std::move(legalized_modified);
1691	    }
1692	  }
1693	
1694	  Stmt VisitStmt_(const BufferStoreNode *op) final {
1695	    auto node = Downcast<BufferStore>(StmtExprMutator::VisitStmt_(op));
1696	    auto [modified, shuffle_index] = VisitBufferAccess(std::move(node));
1697	    ICHECK(shuffle_index < 0);
1698	    return std::move(modified);
1699	  }
1700	
1701	  Stmt VisitStmt_(const LetStmtNode *op) final {
1702	    auto it = rewrite_map_.find(op->var.get());
1703	    PrimExpr value = this->VisitExpr(op->value);
1704	    Stmt body = this->VisitStmt(op->body);
1705	    Var var = (it == rewrite_map_.end()) ? op->var : it->second.new_buffer_var;
1706	    if (var.same_as(op->var) && value.same_as(op->value) &&
1707	        body.same_as(op->body)) {
1708	      return GetRef<Stmt>(op);
1709	    }
1710	    return LetStmt(var, value, body);
1711	  }
1712	
1713	  Buffer RemapBuffer(Buffer buf) {
1714	    auto cache_key = buf.get();
1715	
1716	    auto cache_it = buffer_map_.find(cache_key);
1717	    if (cache_it != buffer_map_.end()) {
1718	      return cache_it->second;
1719	    }
1720	
1721	    auto info_it = rewrite_map_.find(buf->data.get());
1722	    if (info_it != rewrite_map_.end()) {
1723	      auto &info = info_it->second;
1724	
1725	      Array<PrimExpr> shape = buf->shape;
1726	      PrimExpr last_dim = shape[shape.size() - 1];
1727	      shape.Set(shape.size() - 1,
1728	                last_dim / make_const(last_dim.dtype(), info.factor()));
1729	
1730	      auto writer = buf.CopyOnWrite();
1731	      writer->data = info.new_buffer_var;
1732	      writer->dtype = info.new_element_dtype;
1733	      writer->shape = shape;
1734	    }
1735	
1736	    buffer_map_[cache_key] = buf;
1737	    return buf;
1738	  }
1739	
1740	  PrimExpr VisitExpr_(const CallNode *op) final {
1741	    if (op->op.same_as(builtin::tvm_access_ptr())) {
1742	      PrimExpr expr = StmtExprMutator::VisitExpr_(op);
1743	      op = expr.as<CallNode>();
1744	
1745	      if (!rewrite_indices_) {
1746	        return expr;
1747	      }
1748	
1749	      const VarNode *buffer_var = op->args[1].as<VarNode>();
1750	      auto it = rewrite_map_.find(buffer_var);
1751	      if (it == rewrite_map_.end()) {
1752	        return expr;
1753	      }
1754	      const auto &info = it->second;
1755	
1756	      PrimExpr index = op->args[2];
1757	      PrimExpr extent = op->args[3];
1758	      PrimExpr flag = op->args[4];
1759	
1760	      PrimExpr e_dtype = tir::TypeAnnotation(info.new_element_dtype);
1761	      int factor = info.factor();
1762	      extent = extent / make_const(extent.dtype(), factor);
1763	      index = index / make_const(index.dtype(), factor);
1764	      Array<PrimExpr> acc_args{e_dtype, info.new_buffer_var, index, extent,
1765	                               flag};
1766	      return Call(info.new_element_dtype, builtin::tvm_access_ptr(), acc_args);
1767	
1768	    } else {
1769	      return StmtExprMutator::VisitExpr_(op);
1770	    }
1771	  }
1772	
1773	  Stmt VisitStmt_(const AllocateNode *op) final {
1774	    Stmt stmt = StmtExprMutator::VisitStmt_(op);
1775	    op = stmt.as<AllocateNode>();
1776	
1777	    auto it = rewrite_map_.find(op->buffer_var.get());
1778	    if (it == rewrite_map_.end()) {
1779	      return stmt;
1780	    }
1781	
1782	    const auto &info = it->second;
1783	
1784	    Var new_buffer_var = info.new_buffer_var;
1785	
1786	    Array<PrimExpr> extents = op->extents;
1787	    PrimExpr last_extent = extents[extents.size() - 1];
1788	    extents.Set(extents.size() - 1,
1789	                last_extent / make_const(last_extent.dtype(), info.factor()));
1790	    return Allocate(new_buffer_var, info.new_element_dtype, extents,
1791	                    op->condition, op->body, op->annotations);
1792	  }
1793	
1794	  Stmt VisitStmt_(const AllocateConstNode *op) final {
1795	    Stmt stmt = StmtExprMutator::VisitStmt_(op);
1796	    op = stmt.as<AllocateConstNode>();
1797	
1798	    auto it = rewrite_map_.find(op->buffer_var.get());
1799	    if (it == rewrite_map_.end()) {
1800	      return stmt;
1801	    }
1802	
1803	    const auto &info = it->second;
1804	
1805	    Var new_buffer_var = info.new_buffer_var;
1806	
1807	    int factor = info.new_element_dtype.lanes() / op->dtype.lanes();
1808	
1809	    Array<PrimExpr> extents = op->extents;
1810	    extents.Set(extents.size() - 1, extents[extents.size() - 1] /
1811	                                        make_const(extents[0].dtype(), factor));
1812	    return AllocateConst(new_buffer_var, info.new_element_dtype, extents,
1813	                         op->data, op->body);
1814	  }
1815	
1816	  /* Update the parameters and all remaining variable references
1817	   *
1818	   * Should be called after calling operator() on the body of the
1819	   * function.
1820	   *
1821	   * @param func A pointer to the PrimFunc being modified.
1822	   */
1823	  void Finalize(PrimFunc *func_ptr) {
1824	    ICHECK(func_ptr) << "Finalize expects a non-null pointer";
1825	    auto &func = *func_ptr;
1826	    auto *n = func.CopyOnWrite();
1827	
1828	    // Remap any remaining references to the old buffer variables
1829	    Map<Var, Var> var_remap;
1830	    for (const auto &pair : rewrite_map_) {
1831	      const auto &info = pair.second;
1832	      var_remap.Set(info.old_buffer_var, info.new_buffer_var);
1833	    }
1834	    n->body = Substitute(n->body, var_remap);
1835	
1836	    // Remap the argument list to use the new buffer variables.
1837	    Array<Var> new_params;
1838	    for (const auto &old_param : n->params) {
1839	      auto it = rewrite_map_.find(old_param.get());
1840	      if (it == rewrite_map_.end()) {
1841	        new_params.push_back(old_param);
1842	      } else {
1843	        const auto &info = it->second;
1844	        new_params.push_back(info.new_buffer_var);
1845	      }
1846	    }
1847	    n->params = new_params;
1848	
1849	    // Remap the Buffer objects in PrimFunc::buffer_map so that the
1850	    // buffers use the new buffer variables
1851	    Map<Var, Buffer> new_buffer_map;
1852	    for (const auto &pair : n->buffer_map) {
1853	      Var key = pair.first;
1854	      Buffer old_buffer = pair.second;
1855	      Var old_var = old_buffer->data;
1856	      Buffer new_buffer = RemapBuffer(old_buffer);
1857	      new_buffer_map.Set(key, new_buffer);
1858	    }
1859	    n->buffer_map = new_buffer_map;
1860	  }
1861	
1862	private:
1863	  struct RewriteInfo {
1864	    Var old_buffer_var;
1865	    Var new_buffer_var;
1866	    DataType old_element_dtype;
1867	    DataType new_element_dtype;
1868	
1869	    int factor() const {
1870	      int old_lanes = old_element_dtype.lanes();
1871	      int new_lanes = new_element_dtype.lanes();
1872	      ICHECK_EQ(new_lanes % old_lanes, 0);
1873	      return new_lanes / old_lanes;
1874	    }
1875	  };
1876	
1877	  bool rewrite_indices_{true};
1878	  std::unordered_map<const VarNode *, RewriteInfo> rewrite_map_;
1879	  std::unordered_map<const BufferNode *, Buffer> buffer_map_;
1880	  arith::Analyzer analyzer_;
1881	};
1882	
1883	// Rewrite allocates, pointer parameters, and buffer map into vectorized
1884	// versions if each access into a buffer is the same vector type.
1885	PrimFunc PointerValueTypeRewrite(
1886	    PrimFunc f, bool allow_untyped_pointers = false, bool rewrite_params = true,
1887	    bool rewrite_buffer_map = true, bool rewrite_allocate_node = true,
1888	    bool rewrite_indices = true, bool rewrite_let_node = true,
1889	    bool rewrite_allocate_const_node = true,
1890	    bool rewrite_scalar_read_to_vector_shuffle = true) {
1891	  VectorTypeAccessChecker checker(f->params, f->buffer_map,
1892	                                  allow_untyped_pointers,
1893	                                  rewrite_scalar_read_to_vector_shuffle);
1894	  checker(f->body);
1895	  VectorTypeRewriter rewriter(
1896	      checker.info_map_, rewrite_params, rewrite_buffer_map,
1897	      rewrite_allocate_node, rewrite_indices, rewrite_let_node,
1898	      rewrite_allocate_const_node, rewrite_scalar_read_to_vector_shuffle);
1899	  PrimFuncNode *n = f.CopyOnWrite();
1900	  n->body = rewriter(std::move(n->body));
1901	  rewriter.Finalize(&f);
1902	
1903	  return f;
1904	}
1905	
1906	namespace transform {
1907	using namespace tir::transform;
1908	Pass AscendStorageRewrite(bool is_npu = false) {
1909	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
1910	    bool enable_reuse = true;
1911	    bool reuse_require_exact_matched_dtype = false;
1912	    bool merge_static_smem =
1913	        ctx->GetConfig<Bool>("tir.merge_static_smem", Bool(false)).value();
1914	    AllocateCollector collector;
1915	    collector(f->body);
1916	    bool has_dynamic = collector.dyn_shmem_allocs_.size() > 1;
1917	    if (has_dynamic || merge_static_smem) {
1918	      // For IRModule utilizing dynamic shared memory, reuse is not enabled
1919	      // Because dynamic doesn't require maintaining the readability and
1920	      // it benefits from a more optimized allocation strategy through the
1921	      // Pass `MergeSharedMemoryAllocations`.
1922	      // When `merge_static_smem` is true, we will reuse and merge shared
1923	      // memory in a dedicated pass `MergeSharedMemoryAllocations`.
1924	      // And so we don't enable reuse in this pass.
1925	      enable_reuse = false;
1926	    }
1927	
1928	    Optional<Target> target = f->GetAttr<Target>("target");
1929	    if (target.defined() && (target.value()->kind->name == "vulkan" ||
1930	                             target.value()->kind->name == "webgpu")) {
1931	      // Require exactly same-dtype matching in smem reuse for Vulkan and WebGPU
1932	      reuse_require_exact_matched_dtype = true;
1933	    }
1934	
1935	    if (is_npu) {
1936	      // For NPU target, we disable the smem reuse to avoid potential issues.
1937	      enable_reuse = false;
1938	    }
1939	
1940	    Map<Var, PrimExpr> local_var_init_map;
1941	    if (auto init_map =
1942	            f->attrs.GetAttr<Map<Var, PrimExpr>>(tl::attr::kLocalVarInit)) {
1943	      local_var_init_map = init_map.value();
1944	    }
1945	
1946	    auto *n = f.CopyOnWrite();
1947	
1948	    StoragePlanRewriter plan_rewriter;
1949	    n->body = plan_rewriter.Rewrite(std::move(n->body), true, enable_reuse,
1950	                                    reuse_require_exact_matched_dtype,
1951	                                    std::move(local_var_init_map));
1952	    // Parameters may not be rewritten, but internal allocations may.
1953	    // Vectorization of AllocateConst is currently disabled, as it has
1954	    // indexing issues for types that include padding (e.g. int8x3
1955	    // padded out to 32 bits) would require either rewriting
1956	    // AllocateConst::data, or would require the code generators to
1957	    // handle vectorized constants.
1958	    PrimFunc result = PointerValueTypeRewrite(std::move(f), true, false, false,
1959	                                              false, true, true, false, false);
1960	    return result;
1961	  };
1962	  return CreatePrimFuncPass(pass_func, 0, "tl.AscendStorageRewrite", {});
1963	}
1964	
1965	TVM_REGISTER_GLOBAL("tl.transform.AscendStorageRewrite")
1966	    .set_body_typed(AscendStorageRewrite);
1967	
1968	} // namespace transform
1969	
1970	} // namespace tl
1971	} // namespace tvm
